INSERT INTO public.economics_cases
  (subsection, case_id, title, context, statements, answer_key, tactical_explanations, difficulty_level, sort_order, tier)
VALUES
( '3.1', 'CASE 3.1.01', 'Labour as a Factor of Production', 'Analyze how businesses classify human resources among the factors of production used to create goods and services. Evaluate the following economic assertions:', ARRAY['Managers who coordinate schedules supply labour as human resources alongside coordination duties.', 'Insurance claims handlers processing policies supply labour in a service firm.', 'Labour is restricted to manual shop-floor work and excludes planners or accountants.', 'Installing software is a want rather than labour because the service is intangible.', 'Seasonal pickers fall outside labour because their employment lasts only weeks.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Management deploys human resources even when it also involves entrepreneurship.', 'TRUE — Office and service staff are human resources classified as labour.', 'FALSE — Labour includes all human resources, not only physical manual tasks.', 'FALSE — Skilled intangible work is still labour as human resources.', 'FALSE — Paid seasonal workers still supply human resources classified as labour.'], '3/5', 1, 'full' ),
( '3.1', 'CASE 3.1.02', 'Styrian Winemaker Harvest Season', 'Consider a wine-growing business that uses hillside vineyards, seasonal pickers, leased bottling equipment, and specialist fermentation know-how. Evaluate the following economic assertions:', ARRAY['The hillside vineyards represent the land factor as natural resources.', 'Seasonal pickers and the cellar master both supply labour for the winery.', 'The leased bottling line counts as capital even though the winery does not own it.', 'Fermentation knowledge applied to blending draws on knowledge as a production factor.', 'Barrel orders are capital decisions, so entrepreneurship is absent.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Vineyards are natural resources and therefore part of land.', 'TRUE — All human resources in production, seasonal or permanent, are labour.', 'TRUE — Productive equipment used in operations is capital whether owned or leased.', 'TRUE — Production knowledge and experience are important factors in winemaking.', 'FALSE — Coordinating factors and contracts is entrepreneurship.'], '3/5', 2, 'full' ),
( '3.1', 'CASE 3.1.03', 'Land and Natural Resources', 'Analyze what the land factor includes in production. Evaluate the following economic assertions:', ARRAY['River water used to irrigate crops represents a natural-resource land input.', 'Timber ready for milling is land because it originates from trees.', 'Mineral rights are capital because they can be bought and sold.', 'Oak barrels are land because oak comes from forests.', 'Land refers only to fenced factory sites and excludes forests or fisheries.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Water sources used in production are natural resources within land.', 'FALSE — Processed logs for milling are inputs; standing forests are land.', 'FALSE — Unextracted minerals are natural resources within land.', 'FALSE — Processed barrels used in production are capital.', 'FALSE — Land includes fisheries, forests, and minerals as natural resources.'], '2/5', 3, 'full' ),
( '3.1', 'CASE 3.1.04', 'Capital in Production', 'Review statements about capital as a factor of production. Evaluate the following economic assertions:', ARRAY['Leased diagnostic tools used by technicians still function as capital.', 'Spare parts inventory kept for same-day repairs is capital supporting service delivery.', 'Machinery, plant, vehicles, and financial resources used in operations are capital.', 'Cash reserves held to finance payroll between invoice cycles form part of capital.', 'A fleet of delivery vans used to ship finished goods is capital.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Leased equipment used in production is capital.', 'TRUE — Inventories used to deliver services belong to capital.', 'TRUE — Capital includes equipment and financial resources applied to production.', 'TRUE — Financial resources used to operate the business are capital.', 'TRUE — Vehicles used in production and distribution are capital equipment.'], '3/5', 4, 'full' ),
( '3.1', 'CASE 3.1.05', 'Factory Production Shift', 'Consider a manufacturing plant running a shift while sourcing materials and scheduling engineers. Evaluate the following economic assertions:', ARRAY['Production tools and testing equipment on the line are capital in secondary production.', 'Engineers monitoring product quality supply specialised labour.', 'Plant management coordinating materials, staff, and orders supplies entrepreneurship.', 'Materials are land because copper is extracted from the earth.', 'Knowledge is a consumer good unless the firm registers patents.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Manufacturing equipment is part of the capital factor.', 'TRUE — Engineering and inspection work is skilled human resource use.', 'TRUE — Coordinating production factors and timing is entrepreneurship.', 'FALSE — Raw and processed inputs are materials combined with other factors; finished goods are outputs.', 'FALSE — Knowledge applied in production is a recognised factor.'], '3/5', 5, 'full' ),
( '3.1', 'CASE 3.1.06', 'Entrepreneurship as a Factor of Production', 'Review entrepreneurship among the factors of production. Evaluate the following economic assertions:', ARRAY['Entrepreneurship brings land, labour, and capital together to organise production.', 'Uncertainty is borne by lenders alone, not by entrepreneurs.', 'Financial resources are entrepreneurship because both involve business decisions.', 'Hiring staff converts all coordination into labour with no entrepreneurship left.', 'Selecting equipment is capital allocation only, so entrepreneurship is absent.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Entrepreneurship coordinates the other factors and bears organisational responsibility.', 'FALSE — Owners and organisers bear business uncertainty as entrepreneurship.', 'FALSE — Finance is capital; entrepreneurship coordinates rather than replaces it.', 'FALSE — Coordination and risk-bearing remain entrepreneurship with employees present.', 'FALSE — Choosing and organising inputs reflects entrepreneurship.'], '2/5', 6, 'full' ),
( '3.1', 'CASE 3.1.07', 'Knowledge and Technology as Factors', 'Analyze knowledge and technology as production factors. Evaluate the following economic assertions:', ARRAY['Diagnostic software licences used by repair technicians represent technology in services.', 'Experience with fermentation techniques contributes knowledge to winemaking output.', 'Technology used at a repair bench counts as a production factor in a service firm.', 'Technology counts as a factor only where a firm manufactures physical hardware.', 'Design know-how is capital because it is stored on servers.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Technology used to deliver services is a production factor.', 'TRUE — Production knowledge and experience are important factors in practice.', 'TRUE — Technology applied in production matters in services, not only factories.', 'FALSE — Technology also matters in service businesses such as IT support.', 'FALSE — Know-how applied to production is knowledge, not capital by storage medium.'], '3/5', 7, 'full' ),
( '3.1', 'CASE 3.1.08', 'A small IT-support venture Repair Weekend', 'Consider how a small IT-support venture refurbish laptops, install software, and bill for weekend support calls. Evaluate the following economic assertions:', ARRAY['Their venture combines knowledge, labour, technology, capital, and entrepreneurship.', 'Coordinating bookings, parts orders, and repairs supplies entrepreneurship.', 'Repair kits and licensed diagnostic apps form the technology layer of the service offer.', 'Spare screens and batteries held for repairs are capital inputs for the workshop.', 'Staff time spent diagnosing faults counts as the labour input for the repair venture.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Their model uses skills, tools, finance, and coordination together.', 'TRUE — Organising resources and bearing business uncertainty is entrepreneurship.', 'TRUE — Technology used to perform services is a production factor.', 'TRUE — Inventories used to deliver services are capital.', 'TRUE — Support and repair work deploys skilled human resources classified as labour.'], '3/5', 8, 'full' ),
( '3.1', 'CASE 3.1.09', 'Combining Production Factors', 'Analyze how businesses combine factors to create offerings. Evaluate the following economic assertions:', ARRAY['Service firms combine labour with capital, technology, and entrepreneurial coordination.', 'A business combines factors of production to offer goods and/or services to customers.', 'Whichever factor is dominant replaces the need for any other factor.', 'Only manufacturing combines factors; services use labour alone.', 'Automated lines remove labour and knowledge from manufacturing entirely.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Service delivery integrates multiple factors, not labour alone.', 'TRUE — Businesses exist by combining resources to deliver goods or services.', 'FALSE — One dominant factor does not remove the need to combine others.', 'FALSE — Service and manufacturing firms both combine multiple factors.', 'FALSE — Manufacturing still uses labour, knowledge, and coordination alongside capital.'], '3/5', 9, 'full' ),
( '3.1', 'CASE 3.1.10', 'Winemaker Integrated Factors', 'Review factor use in a winemaker''s integrated operations. Evaluate the following economic assertions:', ARRAY['Oak barrels held for ageing wine are capital supporting the production process.', 'Experience with fermentation adds knowledge alongside other factors in winemaking.', 'A winemaker with large vineyards combines land, labour, capital, and entrepreneurship.', 'Vineyard soil fertility is land; bottling machinery at the same site is capital.', 'Only permanent employees supply labour; seasonal staff are excluded.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Equipment and inventories used in production belong to capital.', 'TRUE — Knowledge and experience can be important production factors.', 'TRUE — Winemaking blends natural resources, workforce, equipment, and management.', 'TRUE — Natural resources are land; equipment is capital even on the same property.', 'FALSE — Seasonal and permanent workers both supply human resources as labour.'], '4/5', 10, 'full' ),
( '3.1', 'CASE 3.1.11', 'Entrepreneurship versus Labour', 'Analyze distinctions between entrepreneurship and labour. Evaluate the following economic assertions:', ARRAY['Entrepreneurship and capital are different: capital is resources used; entrepreneurship organises them.', 'Every planning hour is capital because plans are stored digitally.', 'Performing repairs while owning the shop can include both labour and entrepreneurship.', 'Founder coordination of suppliers and staff supplies entrepreneurship separate from task work.', 'Risk-bearing is labour because it consumes working hours.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Capital is resources; entrepreneurship coordinates those resources.', 'TRUE — Planning is human resource work; digital storage does not make it capital.', 'TRUE — Task work is labour; running and coordinating the venture is entrepreneurship.', 'TRUE — Organising factors is entrepreneurship; performing tasks is labour.', 'FALSE — Bearing uncertainty and coordinating resources is entrepreneurship.'], '3/5', 11, 'full' ),
( '3.1', 'CASE 3.1.12', 'Leased Equipment as Capital', 'Analyze whether leased assets count as capital. Evaluate the following economic assertions:', ARRAY['A leased bottling line still functions as capital for a winery in production.', 'Leased warehouse robots used beside manual pickers are capital in a distribution hub.', 'Renting premises means no installed tools count as capital.', 'Hire-purchase machines are land because they stand in a workshop.', 'Seasonal leases turn machinery into land because work happens outdoors.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Capital includes productive equipment whether owned or leased.', 'TRUE — Machinery used in operations is part of the capital factor.', 'FALSE — Leased premises do not reclassify installed tools away from capital.', 'FALSE — Equipment used in production is capital regardless of ownership form.', 'FALSE — Leased harvesters remain capital, not land.'], '2/5', 12, 'full' ),
( '3.1', 'CASE 3.1.13', 'Forestry Crew and Harvesters', 'Consider a forestry crew fells timber using leased harvesters before winter closes mountain access. Evaluate the following economic assertions:', ARRAY['Crew members operating chainsaws and harvesters supply labour.', 'Supervision is labour only and never entrepreneurship in extraction.', 'Trees grow naturally, so logging uses land alone without other factors.', 'Harvesters are land because they operate on forest terrain.', 'Forests become capital once harvesters cut the first tree.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Workers deploying human effort in extraction supply labour.', 'FALSE — Coordinating haulage and crews is entrepreneurship.', 'FALSE — Logging still requires labour, capital, and coordination.', 'FALSE — Leased machinery is capital regardless of location.', 'FALSE — Standing forests remain land; harvesters are capital.'], '3/5', 13, 'full' ),
( '3.1', 'CASE 3.1.14', 'Financial Resources as Capital', 'Review whether financial resources belong to capital. Evaluate the following economic assertions:', ARRAY['Working capital financing payroll between invoice cycles is a financial capital input.', 'Funds borrowed to purchase diagnostic tools are capital applied to production.', 'Capital includes both physical equipment and financial resources used in production.', 'Share capital is the only form of capital a manufacturer may use.', 'Emergency cash is land because it is stored on business premises.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Financial resources supporting operations are part of capital.', 'TRUE — Finance used to acquire productive assets is part of capital.', 'TRUE — Capital covers machinery and finance applied to operations.', 'FALSE — Capital includes equipment and financial resources, not share capital alone.', 'FALSE — Cash held for operations is capital, not land.'], '3/5', 14, 'full' ),
( '3.1', 'CASE 3.1.15', 'Human Skills in Services', 'Review labour in knowledge-intensive service work. Evaluate the following economic assertions:', ARRAY['Only manufacturing floor workers count as labour; service staff are excluded.', 'Technical support staff troubleshooting home networks supply labour.', 'Freelance trainers delivering coaching sessions supply labour to the organising studio.', 'Human skills used to install software for a client count as labour.', 'Labour covers specialists and general staff alike when human resources are deployed.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Service employees are human resources and therefore part of labour.', 'TRUE — Support work is human resource deployment classified as labour.', 'TRUE — Trainers provide human resources classified as labour.', 'TRUE — Skilled technical work deploys human resources classified as labour.', 'TRUE — Labour includes all human resources used in production.'], '2/5', 15, 'full' ),
( '3.1', 'CASE 3.1.16', 'Graz Tailor Workshop', 'Consider a Graz tailor orders sewing machines on hire-purchase and hires two apprentices for a growing workshop. Evaluate the following economic assertions:', ARRAY['Fabric purchased for client orders is a material input combined with labour and machines.', 'The tailor selecting machines and scheduling orders supplies entrepreneurship.', 'Apprentices cutting patterns and stitching garments supply labour.', 'Tailoring needs only labour because designs exist in the tailor''s head.', 'Machines on hire-purchase are land because they occupy workshop space.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Production uses materials alongside labour and capital equipment.', 'TRUE — Organising inputs and production is an entrepreneurial function.', 'TRUE — Workers performing production tasks are human resources classified as labour.', 'FALSE — Tailoring also uses capital, materials, and coordination.', 'FALSE — Production equipment is capital regardless of hire-purchase.'], '3/5', 16, 'full' ),
( '3.1', 'CASE 3.1.17', 'Manufacturing Inputs', 'Review factors used in industrial manufacturing. Evaluate the following economic assertions:', ARRAY['Clean-room tools and testing equipment are capital in secondary production.', 'Engineering teams monitoring material batches supply skilled labour.', 'Fabrication requires labour and materials as well as capital equipment.', 'A components manufacturer combines workforce, materials, equipment, and entrepreneurial direction.', 'Knowledge of process specifications applied on the line is a production factor.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Manufacturing equipment is part of the capital factor.', 'TRUE — Inspection and engineering work is skilled human resource use.', 'TRUE — Manufacturing blends human resources, materials, and machinery.', 'TRUE — Large manufacturers integrate all major factors in production.', 'TRUE — Technical knowledge used in manufacturing counts among production factors.'], '4/5', 17, 'full' ),
( '3.1', 'CASE 3.1.18', 'Technology in Repair Services', 'Analyze technology as a factor in IT repair work. Evaluate the following economic assertions:', ARRAY['Replacing a screen combines labour with capital parts and may use technology tools.', 'A refurbished-laptop workshop uses tools, spare parts, and working capital together.', 'Tools make repairs capital-only with no labour or technology involved.', 'Intangible services exclude technology as a factor.', 'Licences are consumer subscriptions, not production technology.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Repair work integrates labour, capital inventories, and technology.', 'TRUE — Service production combines capital, technology, and labour.', 'FALSE — Repairs combine labour with technology and capital parts.', 'FALSE — Technology applies to services through tools and software used in delivery.', 'FALSE — Software tools used to perform services are technology factors.'], '3/5', 18, 'full' ),
( '3.1', 'CASE 3.1.19', 'Factor Dominance Patterns', 'Analyze how dominant factors differ across industries. Evaluate the following economic assertions:', ARRAY['Knowledge-intensive startups may lean on skills and technology more than heavy land use.', 'Manufacturing weighting capital heavily still leaves entrepreneurship coordinating production.', 'Land-heavy farming still combines labour, equipment, and management.', 'A firm''s dominant factor mix can differ by industry while still combining several inputs.', 'Automation removes all labour and entrepreneurship from capital-intensive plants.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Different businesses weight factors differently depending on activity.', 'TRUE — Entrepreneurship coordinates production even in capital-intensive plants.', 'TRUE — Agriculture integrates multiple factors beyond land alone.', 'TRUE — Industries emphasise different factors yet still combine multiple resources.', 'FALSE — Capital-intensive plants still use labour and coordination.'], '3/5', 19, 'full' ),
( '3.1', 'CASE 3.1.20', 'Vienna Insurance Claims Office', 'Consider a Vienna insurance branch trains new claims handlers on updated case software. Evaluate the following economic assertions:', ARRAY['Claims handlers learning the new system supply labour in the branch.', 'Scheduling training is labour performed by calendars, not people.', 'Premises are land only, so computers there are land as well.', 'Insurance software is the tertiary sector itself, not a factor input.', 'Insurance requires only labour because policies are intangible.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Training and processing work deploys human resources as labour.', 'FALSE — Managers scheduling staff deploy labour and entrepreneurship.', 'FALSE — Premises may involve land; operational computers are capital.', 'FALSE — Software used to deliver services is a technology factor.', 'FALSE — Intangible services still use capital, technology, and coordination.'], '2/5', 20, 'full' ),
( '3.1', 'CASE 3.1.21', 'Carinthian Dairy Co-op Upgrade', 'Consider a Carinthian dairy co-op upgrades cooling tanks to handle higher daily milk volumes. Evaluate the following economic assertions:', ARRAY['The co-op board deciding on tank upgrades supplies entrepreneurship.', 'Milk from member farms links upstream to agricultural land and primary production.', 'Dairy processing at the co-op combines labour, capital, and coordination with upstream land inputs.', 'Cooling tanks and pasteurisers installed at the co-op are capital equipment.', 'Operators monitoring pasteurisation and tank levels supply labour at the co-op.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Strategic coordination of capital investment is entrepreneurial activity.', 'TRUE — Farm output draws on natural resources and primary activity.', 'TRUE — Processing integrates multiple factors beyond land alone.', 'TRUE — Processing machinery is part of the capital factor.', 'TRUE — Processing staff are human resources classified as labour.'], '3/5', 21, 'full' ),
( '3.1', 'CASE 3.1.22', 'Design Know-how in Software Services', 'Review knowledge as a factor in software-related services. Evaluate the following economic assertions:', ARRAY['Training customers on new releases combines labour with knowledge and technology.', 'They use entrepreneurship alone without knowledge or tools.', 'Design stored on servers is capital, not knowledge.', 'Knowledge counts only after formal patent registration.', 'Coding skill is entrepreneurship because programmers take initiative.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Training deploys human resources plus knowledge and technology.', 'FALSE — Their model combines multiple production factors.', 'FALSE — Know-how applied to production is knowledge regardless of storage medium.', 'FALSE — Applied know-how is a factor without patents.', 'FALSE — Initiative on tasks is still labour; coordinating the firm is entrepreneurship.'], '4/5', 22, 'full' ),
( '3.1', 'CASE 3.1.23', 'Seasonal Vineyard Labour', 'Review labour use in seasonal agricultural production. Evaluate the following economic assertions:', ARRAY['A full-time cellar master and seasonal pickers both count as labour for a winery.', 'Seasonal pickers are volunteers outside the labour factor because pay is temporary.', 'Bottling during harvest adds labour alongside land and capital inputs.', 'Labour in harvest includes both pickers and supervisors coordinating field work.', 'Seasonal contracts exclude pickers from the labour factor.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — All human resources in production are classified as labour.', 'TRUE — Paid seasonal workers still supply human resources as labour.', 'TRUE — Processing tasks performed by workers are labour.', 'TRUE — Supervisors and pickers both deploy human resources as labour.', 'FALSE — Short-term paid workers still supply labour.'], '2/5', 23, 'full' ),
( '3.1', 'CASE 3.1.24', 'Vehicle Fleet in Logistics', 'Analyze capital and labour in delivery logistics. Evaluate the following economic assertions:', ARRAY['Delivery vans used to ship circuit boards to customers are capital in manufacturing logistics.', 'Logistics combines capital equipment with labour and coordination.', 'Leased trucks stop being capital because the firm does not own them.', 'Drivers become capital because they operate vehicles.', 'Fuel is land because it comes from natural resources.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Vehicles used for production-related delivery are capital.', 'TRUE — Distribution integrates vehicles, drivers, and management.', 'FALSE — Leased vehicles used in operations are capital.', 'FALSE — Human operators are labour; vehicles remain capital.', 'FALSE — Fuel consumed in operations is an operating cost tied to capital use.'], '3/5', 24, 'full' ),
( '3.1', 'CASE 3.1.25', 'Innsbruck Coaching Studio', 'Consider an Innsbruck coaching studio rents studio space and pays freelance trainers each month. Evaluate the following economic assertions:', ARRAY['Rented studio space and booking systems are capital and technology supporting services.', 'Coaching combines labour with premises, systems, and owner coordination.', 'Freelance trainers delivering sessions supply labour to the studio.', 'Marketing courses is labour performed by customers, not the owner.', 'Freelance trainers replace entrepreneurship entirely in the studio.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Facilities and tools used to deliver services are capital and technology.', 'TRUE — Service delivery integrates multiple factors.', 'TRUE — Trainers provide human resources classified as labour.', 'FALSE — Organising offerings and bookings is entrepreneurship.', 'FALSE — Organisers still provide entrepreneurship alongside contractor labour.'], '3/5', 25, 'full' ),
( '3.1', 'CASE 3.1.26', 'Working Capital and Inventories', 'Review working capital and inventories as capital. Evaluate the following economic assertions:', ARRAY['Cash held to pay suppliers before customer invoices arrive is financial capital.', 'Financial and physical resources used in operations together form capital inputs.', 'Only long-term loans count as capital; day-to-day cash is excluded.', 'Farm-linked equipment is land because milk is agricultural.', 'Inventory is land when it contains metals from mining.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Financial resources supporting operations are part of capital.', 'TRUE — Capital includes both equipment and operating finance.', 'FALSE — Operating finance is included in capital.', 'FALSE — Processing machinery is capital even with agricultural inputs.', 'FALSE — Parts held for service production are capital inventories.'], '3/5', 26, 'full' ),
( '3.1', 'CASE 3.1.27', 'Burgenland Vineyard Barrels', 'Consider a Burgenland vineyard buys oak barrels and contracts seasonal pickers before harvest. Evaluate the following economic assertions:', ARRAY['Oak barrels and bottling equipment held for ageing are capital inputs.', 'Barrel ageing combines land, labour, capital, knowledge, and coordination.', 'Contracted pickers and cellar staff supply labour during harvest and ageing.', 'Grapes are wants, so vineyards are not land.', 'Negotiating contracts is labour done by lawyers only, not entrepreneurs.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Equipment and inventories used in wine production are capital.', 'TRUE — Winemaking integrates multiple factors beyond land alone.', 'TRUE — Workers in production supply human resources as labour.', 'FALSE — Vineyards are natural resources within land.', 'FALSE — Organising contracts and inputs is entrepreneurship.'], '4/5', 27, 'full' ),
( '3.1', 'CASE 3.1.28', 'Production Machinery Roles', 'Review capital equipment and labour on production lines. Evaluate the following economic assertions:', ARRAY['Tooling consumed during extraction, such as drill bits in mining, is capital input.', 'Rental converts machinery into operating expense with no capital role.', 'Automated lines eliminate labour entirely from production.', 'Maintenance is capital because staff repair machines.', 'Automated lines are labour because engineers designed them.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Tools used up in production are capital inputs.', 'FALSE — Leased equipment used in production remains capital.', 'FALSE — Most lines still require labour for operation and maintenance.', 'FALSE — Maintenance workers are labour; machines remain capital.', 'FALSE — Designed machinery is capital; design work is knowledge and labour.'], '2/5', 28, 'full' ),
( '3.1', 'CASE 3.1.29', 'Local IT Service Factor Mix', 'Review combined factors in a local computer repair business. Evaluate the following economic assertions:', ARRAY['Diagnostic equipment and licensed software count as technology supporting the service offer.', 'Technicians replacing screens supply labour while spare parts inventory is capital.', 'Customer training on backups combines knowledge and labour in service delivery.', 'Repair shops combine labour, capital, technology, and coordination.', 'Owners coordinating bookings, parts, and repairs supply entrepreneurship.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Tools and software used to perform services are technology factors.', 'TRUE — Repair work is labour; parts held for service are capital.', 'TRUE — Training applies know-how through human resource work.', 'TRUE — Service firms integrate multiple factors in delivery.', 'TRUE — Organising the venture and bearing risk is entrepreneurship.'], '3/5', 29, 'full' ),
( '3.1', 'CASE 3.1.30', 'Integrated Factor Use', 'Review integrated use of production factors in business. Evaluate the following economic assertions:', ARRAY['Smartphone makers may need electronic components from specialised suppliers to keep production running.', 'Businesses provide goods and services by combining labour, land, capital, entrepreneurship, and often knowledge.', 'A large components manufacturer combines all major factors when producing electronic parts.', 'A small IT-support venture combines knowledge, labour, technology, capital, and entrepreneurship.', 'Dominant factors replace all others in sector analysis.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Component suppliers combine factors to produce inputs other firms need.', 'TRUE — Production draws on multiple listed factors together.', 'TRUE — Large manufacturers integrate labour, materials, equipment, and coordination.', 'TRUE — The venture uses skills, tools, finance, and coordination together.', 'FALSE — Dominance does not eliminate combined use of other factors.'], '3/5', 30, 'full' ),
( '3.1', 'CASE 3.1.31', 'Factor Classification Traps', 'Review subtle misclassification of production factors. Evaluate the following economic assertions:', ARRAY['Natural vineyards are land even when wine is a discretionary product.', 'Optional software makes installation a want, not labour.', 'Approved spending becomes entrepreneurship, not capital.', 'Vision is capital because it can attract money.', 'Machinery on farmland is land because the site is agricultural.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Vineyards are natural resources classified under land.', 'FALSE — Paid technical service work is labour.', 'FALSE — Money for equipment is capital; approval is entrepreneurial decision-making.', 'FALSE — Vision and coordination are entrepreneurship; attracted finance is capital.', 'FALSE — Processing equipment is capital even on agricultural land.'], '4/5', 31, 'full' ),
( '3.1', 'CASE 3.1.32', 'Mining Supplier Shutdown Window', 'Consider a mining supplier must deliver drill bits before a pit shutdown window closes. Evaluate the following economic assertions:', ARRAY['Ore in the pit awaiting extraction represents land as natural resources.', 'Fulfilling the order still requires labour, materials, and coordination beyond capital alone.', 'Drill bits and transport crates held for the shipment are capital inputs.', 'Warehouse staff preparing the drill-bit shipment supply labour.', 'Deadlines convert coordination into labour with no entrepreneurship.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Mineral deposits are natural resources within the land factor.', 'TRUE — Delivery integrates multiple factors, not capital by itself.', 'TRUE — Tools and inventories used in extraction support are capital.', 'TRUE — Workers preparing and dispatching goods supply human resources as labour.', 'FALSE — Coordinating timed delivery is entrepreneurship.'], '5/5', 32, 'full' ),
( '3.1', 'CASE 3.1.33', 'Software Support Knowledge', 'Analyze knowledge and labour in software support services. Evaluate the following economic assertions:', ARRAY['Installing updates for a client is skilled labour deploying human resources.', 'Coordinating the support business is entrepreneurship; performing support is labour.', 'Using computers converts support staff into capital.', 'Knowledge applies only inside factories that fabricate hardware.', 'Troubleshooting is capital because it uses routers and cables.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Paid technical service work is labour.', 'TRUE — Running the venture differs from performing tasks.', 'FALSE — Human operators remain labour; machines are capital.', 'FALSE — Knowledge also matters in service businesses.', 'FALSE — Support work is labour using capital tools.'], '1/5', 33, 'full' ),
( '3.1', 'CASE 3.1.34', 'Dominant Factor Identification', 'Review identifying dominant factors without ignoring others. Evaluate the following economic assertions:', ARRAY['Naming one dominant factor means other factors are irrelevant to production.', 'Capital-intensive plating lines still require labour, materials, and entrepreneurship.', 'A knowledge-intensive startup may weight skills and technology heavily while still using capital.', 'Service-heavy firms still rely on premises, tools, and finance as capital.', 'Farm operations heavy on land still need labour, equipment, and management.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Businesses combine factors even when one is most prominent.', 'TRUE — Heavy capital use does not eliminate other factors.', 'TRUE — Dominant factors differ by model without removing others.', 'TRUE — Service firms use capital alongside labour.', 'TRUE — Agriculture integrates multiple factors beyond land alone.'], '4/5', 34, 'full' ),
( '3.1', 'CASE 3.1.35', 'Distribution Hub Robots', 'Consider a distribution hub adds warehouse robots while keeping manual pick teams for odd-shaped orders. Evaluate the following economic assertions:', ARRAY['Warehouse robots installed beside pick teams are capital equipment.', 'Storage racks and conveyors supporting the hub are capital.', 'Hub management integrating robots and manual teams supplies entrepreneurship.', 'Manual picking is capital because teams use gloves and carts.', 'Automation eliminates labour entirely in every distribution hub.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Automated machinery used in operations is capital.', 'TRUE — Facilities and machinery used in logistics are capital.', 'TRUE — Coordinating mixed systems and staffing is entrepreneurship.', 'FALSE — Pickers are labour; equipment they use is capital.', 'FALSE — Many hubs retain labour alongside capital equipment.'], '3/5', 35, 'full' ),
( '3.1', 'CASE 3.1.36', 'Matching Resources to Factors', 'Review matching resource types to factor definitions. Evaluate the following economic assertions:', ARRAY['Topsoil fertility on a vineyard slope is part of the land factor.', 'Mineral rights to an ore body represent land as a natural resource input.', 'Containers become land when they travel during haulage.', 'Farm-linked machines are land because milk is agricultural.', 'Containers are land because they cross regional borders.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Soil quality is a natural resource within land.', 'TRUE — Subsurface minerals are natural resources within land.', 'TRUE — Transport equipment remains capital during haulage.', 'FALSE — Processing machinery is capital.', 'FALSE — Transport equipment is capital, not land.'], '2/5', 36, 'full' ),
( '3.1', 'CASE 3.1.37', 'Mixed-factor Service Firms', 'Review factor combination in tertiary service businesses. Evaluate the following economic assertions:', ARRAY['Coaching studios combine rented premises, trainers'' labour, and owner coordination.', 'Tertiary firms exclude capital because services are intangible.', 'Insurance uses labour only because policies are intangible.', 'Repairs are labour-only because customers bring devices.', 'Training converts all inputs into tertiary output with no factors.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Services use capital, labour, and entrepreneurship together.', 'TRUE — Service firms still use premises, tools, and finance as capital.', 'FALSE — Insurance also uses technology, capital, and coordination.', 'FALSE — Workshops still use parts, tools, and technology.', 'FALSE — Training uses knowledge through labour.'], '5/5', 37, 'full' ),
( '3.1', 'CASE 3.1.38', 'Entrepreneurial Coordination Examples', 'Analyze entrepreneurship in coordinating other factors. Evaluate the following economic assertions:', ARRAY['Coordinating a repair shop''s parts orders and bookings supplies entrepreneurship.', 'Scheduling production shifts while sourcing materials reflects entrepreneurship at a manufacturer.', 'Integrating robots with manual pick teams reflects entrepreneurship in logistics.', 'Any purchase decision is entrepreneurship simply because money is spent.', 'Selecting barrel suppliers and picker contracts reflects entrepreneurship at a winery.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — Organising resources and operations is entrepreneurship.', 'TRUE — Coordinating production inputs and timing is entrepreneurship.', 'TRUE — Designing how factors combine operationally is entrepreneurial work.', 'FALSE — Spending alone is not entrepreneurship; entrepreneurship organises and combines factors.', 'TRUE — Organising inputs and contracts is entrepreneurial coordination.'], '2/5', 38, 'full' ),
( '3.1', 'CASE 3.1.39', 'Repair Shop Capital Inputs', 'Review capital and labour in a computer repair workshop. Evaluate the following economic assertions:', ARRAY['The workshop combines labour, capital, technology, and coordination to deliver repairs.', 'Answering phones converts all activity into entrepreneurship with no labour.', 'Screen replacement is capital-only because parts are tangible goods.', 'Spare parts are wants sold to customers, not capital inputs.', 'Software licences are tertiary output and cannot be factor inputs.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Service firms integrate multiple factors in delivery.', 'FALSE — Performing repairs is labour; coordinating the firm is entrepreneurship.', 'FALSE — Installation work is labour; parts are capital.', 'FALSE — Parts held for service production are capital inventories.', 'FALSE — Tools used to deliver services are technology factors.'], '3/5', 39, 'full' ),
( '3.1', 'CASE 3.1.40', 'Workforce and Materials in Manufacturing', 'Review whether manufacturing can run on capital alone. Evaluate the following economic assertions:', ARRAY['Plant managers coordinating shifts and suppliers supply entrepreneurship.', 'Quality inspectors monitoring batches supply skilled labour on the line.', 'Manufacturing requires engineers, operators, and materials alongside equipment.', 'Materials stored for production are combined with capital and labour.', 'Component plants run on capital alone once equipment is installed.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Coordinating production factors is entrepreneurship.', 'TRUE — Inspection work is skilled human resource use.', 'TRUE — Manufacturing still requires labour, materials, and coordination.', 'TRUE — Manufacturing uses materials alongside capital and labour.', 'FALSE — Manufacturing integrates labour, materials, equipment, and coordination.'], '4/5', 40, 'full' ),
( '3.1', 'CASE 3.1.41', 'Vineyard Land versus Barrels', 'Review land and capital distinctions in winemaking. Evaluate the following economic assertions:', ARRAY['Machinery on vineyard land is capital even though the site is agricultural.', 'Vineyard parcels and grape production draw on land as natural resources.', 'Fermentation knowledge applied to blending is a knowledge production factor.', 'River water rights used for irrigation represent natural-resource land inputs.', 'Barrels are land because oak originates from forests.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Equipment used in processing is capital, not land.', 'TRUE — Vineyards and agricultural output relate to the land factor.', 'TRUE — Production knowledge and experience are important factors.', 'TRUE — Water sources used in production are natural resources within land.', 'FALSE — Processed barrels used in production are capital.'], '2/5', 41, 'full' ),
( '3.1', 'CASE 3.1.42', 'A small IT-support venture Factor Bundle', 'Analyze the factor bundle in a laptop repair and software venture. Evaluate the following economic assertions:', ARRAY['Hands-on technical fault-finding by staff is counted as the labour factor among the firm''s resources.', 'Licensed diagnostic software and repair tools represent technology in the service model.', 'Refurbishing laptops uses spare parts inventory as capital.', 'The venture relies on entrepreneurship alone with no other factors.', 'Customer contact replaces all other factors in the venture.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Support and repair work deploys skilled human resources.', 'TRUE — Technology used to perform services is a production factor.', 'TRUE — Inventories used to deliver services are capital.', 'FALSE — Their repair and software work combines multiple production factors.', 'FALSE — Coordination and risk-bearing are entrepreneurship.'], '5/5', 42, 'full' ),
( '3.1', 'CASE 3.1.43', 'Entrepreneurship versus Capital Trap', 'Review traps confusing entrepreneurship with capital. Evaluate the following economic assertions:', ARRAY['Founder vision coordinating suppliers is entrepreneurship rather than capital.', 'Cash reserves are entrepreneurship because founders control spending.', 'Entrepreneurship and capital are interchangeable labels for spending.', 'Purchasing machinery converts spending entirely into entrepreneurship.', 'Borrowed finance is entrepreneurship because borrowing shows initiative.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Vision and coordination belong to entrepreneurship, not capital.', 'FALSE — Operating cash is capital; spending decisions may reflect entrepreneurship.', 'FALSE — Capital is resources used; entrepreneurship organises those resources.', 'FALSE — Purchasing equipment is capital use; organising purchases is entrepreneurship.', 'FALSE — Borrowed finance used for equipment is financial capital.'], '1/5', 43, 'full' ),
( '3.1', 'CASE 3.1.44', 'Knowledge in Service Firms', 'Review knowledge as a factor outside manufacturing plants. Evaluate the following economic assertions:', ARRAY['Design know-how for customer software counts as knowledge in service production.', 'Coding skill deployed on client projects is skilled labour using knowledge.', 'Technology and knowledge both matter in repair and software services.', 'Training customers on backups applies knowledge through skilled labour.', 'Experience with fermentation contributes knowledge to winemaking output.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Know-how applied to deliver services is part of knowledge as a factor.', 'TRUE — Programming work is labour applying know-how.', 'TRUE — Service firms apply know-how and tools alongside labour.', 'TRUE — Training deploys know-how via human resource work.', 'TRUE — Production knowledge and experience are important factors.'], '4/5', 44, 'full' ),
( '3.1', 'CASE 3.1.45', 'Seasonal and Permanent Labour', 'Review labour classification for seasonal and permanent workers. Evaluate the following economic assertions:', ARRAY['Insurance handlers trained on new software supply labour in a service branch.', 'Seasonal grape pickers supply labour even when contracts last only weeks.', 'Only permanent employees can supply labour in production.', 'Freelancers replace entrepreneurship entirely in a coaching studio.', 'Specialists supply entrepreneurship only, not labour.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Office and service staff are human resources classified as labour.', 'TRUE — Short-term workers are human resources within the labour factor.', 'FALSE — Permanent and seasonal workers both supply labour.', 'FALSE — Contractors supply labour; the organiser provides entrepreneurship.', 'FALSE — Specialists deploying human effort are labour.'], '2/5', 45, 'full' ),
( '3.1', 'CASE 3.1.46', 'Factor Combination Requirement', 'Review whether businesses can rely on a single factor. Evaluate the following economic assertions:', ARRAY['Manufacturing blends labour, capital, materials, knowledge, and coordination.', 'Dominant factor emphasis in an industry removes other factors from production.', 'A firm can deliver goods using one dominant factor without combining others.', 'Services need only labour because output is intangible.', 'Winemaking needs only land because grapes ripen naturally.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Manufacturing integrates multiple factors rather than one alone.', 'FALSE — Businesses still combine factors even when one appears dominant.', 'FALSE — Businesses combine multiple factors rather than one alone.', 'FALSE — Services still rely on capital, technology, and coordination.', 'FALSE — Winemaking also requires labour, capital, and management.'], '3/5', 46, 'full' ),
( '3.1', 'CASE 3.1.47', 'Financial and Physical Capital', 'Review financial resources alongside physical capital. Evaluate the following economic assertions:', ARRAY['Equipment, plant, vehicles, and operating finance applied in production count as capital.', 'Entrepreneurship replaces capital once founders approve equipment purchases.', 'Leased bottling lines and hired harvesters still function as capital.', 'Working capital financing payroll between invoice cycles is financial capital.', 'Spare parts inventory for repairs is capital supporting service delivery.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Capital includes equipment and financial resources.', 'TRUE — Purchasing equipment is capital; organising purchases is entrepreneurship.', 'TRUE — Leased productive equipment still counts as capital.', 'TRUE — Financial resources supporting operations are part of capital.', 'TRUE — Inventories used in operations belong to capital.'], '3/5', 47, 'full' ),
( '3.1', 'CASE 3.1.48', 'Integrated Production Examples', 'Review integrated factor use across firm types. Evaluate the following economic assertions:', ARRAY['Identifying one example factor in a firm eliminates the need to consider others.', 'A small IT-support venture shows how knowledge, labour, technology, capital, and entrepreneurship work together.', 'Smartphone makers needing electronic components from suppliers rely on combined factors upstream.', 'A winemaker illustrates combining land, labour, capital, entrepreneurship, and experience.', 'A large components manufacturer illustrates capital-only production without workforce.'], ARRAY[false, true, true, true, false], ARRAY['FALSE — Businesses combine factors even when examples emphasise one.', 'TRUE — The venture uses skills, tools, finance, and coordination.', 'TRUE — Component suppliers combine factors to produce inputs.', 'TRUE — Winemaking blends multiple listed factors.', 'FALSE — Manufacturing integrates labour, materials, equipment, and coordination.'], '2/5', 48, 'full' ),
( '3.1', 'CASE 3.1.49', 'Land versus Capital on One Site', 'Review land and capital distinctions on the same production site. Evaluate the following economic assertions:', ARRAY['Bottling machinery installed beside the vines is capital.', 'Harvest coordination is labour performed by grapes, not entrepreneurs.', 'Vines are wants, so vineyards are excluded from the land factor.', 'Agricultural sites use land alone without labour or equipment.', 'Pickers are land inputs because they work among vines.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Equipment used in processing is capital.', 'FALSE — Coordinating harvest and equipment is entrepreneurship.', 'FALSE — Vineyards are natural resources classified under land.', 'FALSE — Farming and processing combine multiple factors.', 'FALSE — Seasonal workers are human resources classified as labour.'], '3/5', 49, 'full' ),
( '3.1', 'CASE 3.1.50', 'Factors of Production Synthesis', 'Review integrated claims about factors of production. Evaluate the following economic assertions:', ARRAY['Businesses combine labour, land, capital, entrepreneurship, and often knowledge to create offerings.', 'A large components manufacturer illustrates combining all major factors in industrial production.', 'A refurbished-laptop venture combines knowledge, labour, technology, capital, and entrepreneurship.', 'Winemaking illustrates land-only production in agriculture.', 'Dominant factors make other factors irrelevant in analysis.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Production typically integrates multiple listed factors.', 'TRUE — Large manufacturers integrate workforce, materials, equipment, and coordination.', 'TRUE — The venture uses skills, tools, finance, and coordination together.', 'FALSE — Winemaking combines multiple factors beyond land.', 'FALSE — Dominance does not remove combined use of other factors.'], '4/5', 50, 'full' ),
( '3.2', 'CASE 3.2.01', 'Three-sector Model Basics', 'Review the primary, secondary, and tertiary sectors as stages from extraction through manufacturing to services. Evaluate the following economic assertions:', ARRAY['Mining ore is primary-sector activity while smelting metal ingots is secondary.', 'The tertiary sector comprises services such as banking, insurance, and coaching.', 'The primary sector covers farming, fishing, mining, and forestry extracting raw materials.', 'Banking and insurance belong to the primary sector because they are basic needs.', 'The secondary sector delivers banking and insurance services to households.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Mining is primary; smelting and manufacturing are secondary.', 'TRUE — Tertiary activity delivers services rather than extracting or manufacturing goods.', 'TRUE — Primary activity extracts raw materials from the earth.', 'FALSE — Banking and insurance are tertiary services, not primary extraction.', 'FALSE — Banking and insurance are tertiary services, not secondary manufacturing.'], '3/5', 1, 'full' ),
( '3.2', 'CASE 3.2.02', 'Tyrolean Ski Resort Services', 'Consider a Tyrolean ski resort hires instructors and sells lift passes to local visitors. Evaluate the following economic assertions:', ARRAY['Selling lift passes and ski instruction are tertiary services.', 'Instructors supply capital because they teach on mountain slopes.', 'Manufacturing skis on site would remain tertiary because guests consume the experience.', 'Guest services at a ski resort are primary extraction because snow is natural.', 'The resort belongs to the primary sector because it operates on a mountainside.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Recreation services and instruction are tertiary activity.', 'FALSE — Human resources delivering services are classified as labour.', 'FALSE — Producing physical goods from materials is secondary manufacturing.', 'FALSE — Natural setting does not reclassify service delivery as primary extraction.', 'FALSE — Location does not make a service business primary; activity type determines sector.'], '2/5', 2, 'full' ),
( '3.2', 'CASE 3.2.03', 'Primary Sector Activities', 'Analyze classification of primary-sector activity. Evaluate the following economic assertions:', ARRAY['A coal mine extracting ore belongs to the primary sector.', 'An olive farm harvesting and pressing oil performs primary agricultural activity.', 'Forestry concessions supplying logs to mills belong to the primary sector.', 'Milling logs into export boards at a timber mill is secondary manufacturing.', 'Commercial fishing that lands herring for sale is primary-sector extraction.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Mining extracts raw materials and is primary-sector activity.', 'TRUE — Growing and harvesting crops is primary-sector activity.', 'TRUE — Forestry extracts natural resources and is primary activity.', 'TRUE — Milling into boards is secondary manufacturing.', 'TRUE — Commercial fishing extracts natural resources and is primary activity.'], '3/5', 3, 'full' ),
( '3.2', 'CASE 3.2.04', 'Secondary Manufacturing', 'Review what counts as secondary-sector manufacturing. Evaluate the following economic assertions:', ARRAY['Retail sale of finished jackets is tertiary distribution or trade.', 'Warehousing steel before welding is a tertiary logistics service.', 'A car plant assembling vehicles operates in the tertiary sector because it serves customers.', 'A fashion label sewing jackets performs tertiary retail because jackets are sold later.', 'Smelters shaping metal remain primary because ore originates underground.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Selling to consumers is tertiary distribution/trade.', 'TRUE — Warehousing and logistics are tertiary services.', 'FALSE — Vehicle assembly from processed materials is secondary manufacturing.', 'FALSE — Garment production from materials is secondary even if products are later retailed.', 'FALSE — Processing ore or metal into usable forms is secondary transformation.'], '2/5', 4, 'full' ),
( '3.2', 'CASE 3.2.05', 'Flood Rebuild and GDP', 'Consider how, after floods a municipality rebuilds bridges and the spending enters national accounts. Evaluate the following economic assertions:', ARRAY['Measured GDP can rise after ecological disasters that require infrastructure repair.', 'Construction spending on bridge rebuilds is included in GDP measurement.', 'Rebuild spending can raise measured GDP while citizen wellbeing falls.', 'GDP reflects monetary value of final goods and services produced within national borders.', 'Rebuild activity proves GDP always equals citizen wellbeing after disasters.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Disaster recovery spending increases GDP even when welfare falls.', 'TRUE — Rebuild spending adds to measured GDP.', 'TRUE — GDP can increase from rebuilds even when underlying welfare declined.', 'TRUE — GDP sums final domestic production over a defined period.', 'FALSE — GDP can rise from rebuilds even when underlying welfare declined.'], '4/5', 5, 'full' ),
( '3.2', 'CASE 3.2.06', 'Tertiary Services Scope', 'Review the scope of tertiary-sector services. Evaluate the following economic assertions:', ARRAY['Banking branches providing loans perform tertiary financial services.', 'Remote coaching sessions sold to foreign clients are tertiary services.', 'Smelting metal ingots from ore on site is secondary manufacturing.', 'Software helpdesks troubleshooting home networks provide tertiary services.', 'Insurance cooperatives processing claims provide primary extraction services.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Banking is classified within the tertiary sector.', 'TRUE — Coaching is a service regardless of client location.', 'TRUE — Smelting and manufacturing belong to the secondary sector.', 'TRUE — Technical support is a tertiary service.', 'FALSE — Insurance is a financial service, not resource extraction.'], '4/5', 6, 'full' ),
( '3.2', 'CASE 3.2.07', 'Emerging Economy Sector Mix', 'Analyze sector patterns in emerging economies. Evaluate the following economic assertions:', ARRAY['Heavy farming employment in less developed countries signals primary-sector dominance.', 'Primary-sector share typically shrinks as economic development advances.', 'Emerging economies show smaller primary shares than advanced EU states.', 'Emerging economies typically report tertiary output above seventy percent of GDP.', 'Advanced services above seventy percent of output characterises most emerging economies.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Emerging countries often rely heavily on primary-sector output.', 'TRUE — Development shifts activity toward secondary and tertiary sectors.', 'FALSE — Emerging countries often rely heavily on primary-sector output.', 'FALSE — Emerging economies depend more on primary activity, not dominant tertiary shares.', 'FALSE — Emerging economies depend more on primary activity rather than dominant tertiary shares.'], '2/5', 7, 'full' ),
( '3.2', 'CASE 3.2.08', 'Olive Farm and Factory Order', 'Consider a farm selling olive oil while a factory fills an industrial production order. Evaluate the following economic assertions:', ARRAY['Fabricating electronic components transforms materials and therefore belongs to secondary manufacturing.', 'The farm is secondary because bottled oil is a processed product.', 'Both activities belong to the tertiary sector because each sells to customers.', 'Fabricating components from materials is tertiary because parts go to other businesses.', 'Harvesting and pressing olives on the farm is tertiary because oil is sold to customers.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Component production transforms materials into manufactured goods.', 'FALSE — Agricultural production and harvesting remain primary even if some processing occurs on farm.', 'FALSE — Selling does not reclassify farming or manufacturing into services.', 'FALSE — Manufacturing for business customers remains secondary activity.', 'FALSE — Agricultural production remains primary even when products are sold.'], '1/5', 8, 'full' ),
( '3.2', 'CASE 3.2.09', 'Developed EU Tertiary Share', 'Review tertiary dominance in advanced European economies. Evaluate the following economic assertions:', ARRAY['Advanced EU economies are service-dominated despite the importance of food production.', 'In highly developed EU economies the tertiary sector often exceeds seventy percent of output.', 'Higher GDP per capita in EU member states links to high living standards in the model.', 'A seventy percent-plus service share reflects primary dominance in advanced economies.', 'Developed EU states keep primary output above seventy percent because food is essential.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Developed EU economies are service-dominated despite food importance.', 'TRUE — Advanced EU countries typically see services dominate total output.', 'TRUE — GDP per capita is used as a living-standard indicator.', 'FALSE — High tertiary shares typify advanced, not primary-dominated, economies.', 'FALSE — In developed EU countries the tertiary sector usually exceeds seventy percent.'], '3/5', 9, 'full' ),
( '3.2', 'CASE 3.2.10', 'Gross Domestic Product Definition', 'Review the definition of gross domestic product as a measure of overall economic activity within a country. Evaluate the following economic assertions:', ARRAY['GDP counts final goods and services rather than intermediate goods sold between factories.', 'GDP is usually calculated for final production within one year inside national borders.', 'GDP totals the monetary value of final goods and services produced within a country''s borders.', 'GDP measures production within borders regardless of firm nationality.', 'Final services such as insurance produced domestically enter GDP totals.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — GDP avoids double counting by focusing on final output.', 'TRUE — GDP typically refers to annual domestic final production.', 'TRUE — GDP measures final domestic production over a defined period.', 'TRUE — GDP is based on geography of production.', 'TRUE — GDP includes final services produced within borders.'], '5/5', 10, 'full' ),
( '3.2', 'CASE 3.2.11', 'EU Services at Seventy-four Percent', 'Consider a GDP report for an EU member state shows services at seventy-four percent of total output. Evaluate the following economic assertions:', ARRAY['Service share alone does not prove every component of GDP is environmentally sustainable.', 'Seventy-four percent services indicates tertiary dominance rather than primary leadership.', 'Such a share is typical for economically advanced EU countries.', 'Seventy-four percent service share fits a highly developed EU economy pattern.', 'That pattern reflects rising relative importance of tertiary activity with development.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — GDP share does not by itself show sustainability of growth.', 'TRUE — The reported figure shows services dominating total output.', 'TRUE — High tertiary shares characterise advanced EU states.', 'TRUE — Advanced EU economies often exceed seventy percent tertiary output.', 'TRUE — More developed economies shift toward services in the three-sector model.'], '5/5', 11, 'full' ),
( '3.2', 'CASE 3.2.12', 'GDP Growth Measure', 'Analyze how GDP growth is assessed over time. Evaluate the following economic assertions:', ARRAY['GDP growth compares inflation-adjusted GDP across years.', 'Real GDP per capita can rise after stripping out inflation from nominal figures.', 'Real GDP strips price changes to compare volume of production over time.', 'Nominal GDP increases always equal real economic growth.', 'Ignoring inflation never affects growth comparisons between years.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Real growth uses GDP adjusted for inflation.', 'TRUE — Inflation-adjusted per capita figures support growth comparisons.', 'TRUE — Inflation adjustment isolates real output changes.', 'FALSE — Price rises can inflate nominal GDP without real output gains.', 'FALSE — Real comparisons generally require inflation adjustment.'], '3/5', 12, 'full' ),
( '3.2', 'CASE 3.2.13', 'Remote Coaching Abroad', 'Consider an Estonian coach delivers remote training sessions to clients in other countries. Evaluate the following economic assertions:', ARRAY['Remote delivery to foreign clients keeps the activity tertiary.', 'Exporting advice does not convert coaching into secondary manufacturing.', 'Remote coaching is primary because trainers work from home offices.', 'Because no goods cross borders, the activity cannot be counted in GDP.', 'Selling coaching sessions is primary extraction because trainers work from home offices.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Coaching remains a service regardless of client location.', 'TRUE — Coaching stays a service even when clients are abroad.', 'FALSE — Home offices are locations for delivering services, not extracting raw materials.', 'FALSE — Services produced domestically can count in home-country GDP.', 'FALSE — Coaching advice is a service output, not extraction of natural resources.'], '2/5', 13, 'full' ),
( '3.2', 'CASE 3.2.14', 'Coal Mine and Car Plant Quarter', 'Consider a Romanian coal mine and a Graz car plant report output in the same quarter. Evaluate the following economic assertions:', ARRAY['Coal extraction at the mine is primary-sector activity.', 'Vehicle assembly at the car plant is secondary manufacturing.', 'Steel inputs from mining do not make vehicle assembly primary activity.', 'Office staff at a mine or plant do not reclassify core production into tertiary services.', 'Both plants belong to the tertiary sector because they employ office staff.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Mining extracts raw materials and is primary activity.', 'TRUE — Assembling cars from materials is secondary activity.', 'TRUE — Assembly of vehicles is secondary even if inputs came from mining.', 'TRUE — Core extraction and manufacturing sectors remain primary and secondary.', 'FALSE — Office staff do not reclassify extraction or manufacturing into services.'], '4/5', 14, 'full' ),
( '3.2', 'CASE 3.2.15', 'GDP Income Coverage Critique', 'Review criticisms that GDP misses some income. Evaluate the following economic assertions:', ARRAY['GDP omission of some income sources is one reason its use is debated.', 'Every barter transaction is always fully recorded in official GDP.', 'Unpaid home maintenance done by owners is always included in GDP.', 'GDP fully captures household volunteering and unpaid care in its totals.', 'Household volunteering and unpaid care are always counted in official GDP totals.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Incomplete income coverage contributes to GDP criticism.', 'FALSE — Informal and non-market activity is often missed by GDP.', 'FALSE — Non-market unpaid work is typically outside GDP scope.', 'FALSE — Unpaid care work typically falls outside GDP measurement boundaries.', 'FALSE — Volunteer labour is generally excluded from official GDP aggregates.'], '1/5', 15, 'full' ),
( '3.2', 'CASE 3.2.16', 'Insurance Branch and Wheat Farm', 'Consider an insurance cooperative processes claims while a nearby farm harvests wheat. Evaluate the following economic assertions:', ARRAY['Farm output and insurance services can coexist as primary and tertiary activity.', 'Both operations are tertiary because each serves customers.', 'Claims handling at the insurance branch is primary because policies cover basic risks.', 'Harvesting wheat is secondary manufacturing because flour milling follows.', 'Wheat farming is secondary because grain is processed into flour elsewhere.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Different sectors operate side by side in the same economy.', 'FALSE — Customer service does not make farming tertiary.', 'FALSE — Insurance is a financial service, not resource extraction.', 'FALSE — Farming wheat from land is primary agriculture, not secondary manufacturing.', 'FALSE — Grain harvesting remains primary even when processed into flour later.'], '3/5', 16, 'full' ),
( '3.2', 'CASE 3.2.17', 'Sustainability and GDP Quality', 'Review GDP as an indicator of sustainable or high-quality growth. Evaluate the following economic assertions:', ARRAY['GDP does not tell whether growth damages resources or wellbeing.', 'GDP alone reveals little about the quality or sustainability of economic growth.', 'Rebuilds after disasters can raise GDP without improving quality of life.', 'Rising GDP may coincide with pollution or resource depletion.', 'Quality concerns are unrelated to debates about GDP as a welfare measure.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — GDP misses quality and sustainability dimensions critics highlight.', 'TRUE — GDP does not by itself show sustainability or quality of growth.', 'TRUE — Measured output can rise while welfare remains impaired.', 'TRUE — Output can grow without environmental improvement.', 'FALSE — Quality and sustainability are standard GDP criticisms.'], '5/5', 17, 'full' ),
( '3.2', 'CASE 3.2.18', 'Port Warehouse and Shipyard', 'Consider a port warehouse stores imported steel before a shipyard welds hull sections. Evaluate the following economic assertions:', ARRAY['Mining origins of steel do not make warehousing or shipbuilding primary.', 'The chain shows tertiary logistics feeding secondary production.', 'Welding hull sections at the shipyard is secondary manufacturing.', 'Building ships from steel plate is secondary manufacturing.', 'Warehousing imported steel before fabrication is a tertiary logistics service.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Downstream storage and shipbuilding are not primary extraction.', 'TRUE — Services can support manufacturing downstream.', 'TRUE — Welding hull sections transforms materials into manufactured vessels.', 'TRUE — Ship construction from steel plate counts as secondary manufacturing output.', 'TRUE — Storage and logistics are tertiary services.'], '3/5', 18, 'full' ),
( '3.2', 'CASE 3.2.19', 'Clinic Expansion and Real GDP', 'Consider a Prague clinic expands while real GDP per capita rises after inflation adjustment. Evaluate the following economic assertions:', ARRAY['Real GDP per capita rising after inflation adjustment indicates real growth.', 'Basic need status does not reclassify healthcare delivery as primary activity.', 'Nominal GDP increases alone do not prove real growth without price adjustment.', 'Clinic growth is primary because health is a basic need.', 'Healthcare expansion cannot occur while real GDP per capita rises.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Inflation-adjusted GDP supports real growth comparisons.', 'TRUE — Healthcare provision is tertiary service activity.', 'TRUE — Real growth requires adjusting for inflation.', 'FALSE — Healthcare provision is tertiary service activity.', 'FALSE — Sector activity contributes to overall measured GDP growth.'], '4/5', 19, 'full' ),
( '3.2', 'CASE 3.2.20', 'Disaster Rebuild GDP Effect', 'Review how disaster recovery affects measured GDP. Evaluate the following economic assertions:', ARRAY['Rebuilding infrastructure after ecological damage can raise measured GDP.', 'Recovery and rebuild spending adds to measured output.', 'GDP rising after disasters proves living standards improved.', 'Cleanup spending automatically reduces GDP because it repairs harm.', 'Disaster rebuilds exclude construction wages from GDP to avoid counting damage twice.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Reconstruction outlays enter GDP as new final expenditure.', 'TRUE — Repair and rebuild contracts add to measured national output totals.', 'FALSE — GDP may rise from rebuilds without restoring lost welfare.', 'FALSE — Recovery and rebuild spending adds to measured output.', 'FALSE — Rebuild spending is included and can raise GDP.'], '1/5', 20, 'full' ),
( '3.2', 'CASE 3.2.21', 'Fishing Fleet and Fashion Label', 'Consider a fishing fleet lands herring while a fashion label sews jackets from imported fabric. Evaluate the following economic assertions:', ARRAY['Garment manufacturing from imported fabric is secondary activity.', 'Landing herring for sale is primary-sector fishing activity.', 'Onboard filleting converts commercial fishing into secondary processing.', 'Both firms are primary because they use natural or imported inputs.', 'Fashion sewing is tertiary because designs are creative services.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Garment production from materials is secondary activity.', 'TRUE — Commercial fishing extracts resources and is primary activity.', 'FALSE — Extracting fish remains primary-sector activity.', 'FALSE — Garment manufacturing is secondary, not primary.', 'FALSE — Sewing garments is manufacturing in the secondary sector.'], '2/5', 21, 'full' ),
( '3.2', 'CASE 3.2.22', 'A small IT-support venture Sector Classification', 'Analyze how to classify a small IT-support venture''s trading, software, and support activities. Evaluate the following economic assertions:', ARRAY['Developing software for customers is tertiary service activity.', 'Refurbishing laptops and providing support are tertiary service activities.', 'A small IT-support venture trade goods, develop software, and provide technical support in the tertiary sector.', 'Minerals inside devices do not reclassify their support activity as primary extraction.', 'Handling physical laptops does not move their support work into secondary manufacturing.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Software services are tertiary, not manufacturing, in this context.', 'TRUE — Repair and support are tertiary service activities.', 'TRUE — Their activities are classified as services in the tertiary sector.', 'TRUE — Using devices does not make their support activity primary.', 'TRUE — Repair and support are services even when goods are involved.'], '5/5', 22, 'full' ),
( '3.2', 'CASE 3.2.23', 'Mining Pit and Smelters Chain', 'Consider a mining pit extracts ore while downstream smelters shape metal for machinery plants. Evaluate the following economic assertions:', ARRAY['Smelters shaping metal perform secondary transformation.', 'Smelting ore into metal stays primary extraction rather than secondary processing.', 'The entire chain from pit to machinery is primary because metal is natural.', 'Every downstream step from pit to machinery counts as primary because metal is natural.', 'Smelting remains primary because ore comes directly from the earth.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Processing ore into metal is secondary activity.', 'FALSE — Processing ore into metal is secondary transformation.', 'FALSE — Smelting transforms extracted ore; only pit extraction is primary.', 'FALSE — Machinery assembly downstream is secondary, not primary extraction.', 'FALSE — Natural origin of ore does not keep smelting in the primary sector.'], '2/5', 23, 'full' ),
( '3.2', 'CASE 3.2.24', 'Inflation-adjusted Growth', 'Analyze the role of inflation adjustment in GDP growth. Evaluate the following economic assertions:', ARRAY['Comparing GDP across years requires adjusting for inflation to measure real growth.', 'Inflation adjustment is generally required for meaningful real growth comparisons.', 'Nominal and real growth align closely when prices are stable.', 'Ignoring inflation can overstate growth when prices rise faster than output.', 'Real GDP includes all price changes when comparing production over time.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Real growth uses inflation-adjusted GDP.', 'TRUE — Real comparisons generally require inflation adjustment.', 'TRUE — With stable prices nominal and real growth align closely.', 'TRUE — Nominal figures can inflate apparent growth without real gains.', 'FALSE — Real growth uses GDP adjusted for inflation.'], '1/5', 24, 'full' ),
( '3.2', 'CASE 3.2.25', 'Bookstore Distribution Branch', 'Consider a bookstore branch distributes publishers'' titles to local readers. Evaluate the following economic assertions:', ARRAY['Printing the titles at a publisher''s plant is secondary manufacturing.', 'Retail trade of printed titles is tertiary activity.', 'Distributing publishers'' titles to readers is tertiary distribution activity.', 'Book sales are secondary because books are physical products.', 'Reading promotion events turn bookstores into primary agriculture.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Printing books is manufacturing in the secondary sector.', 'TRUE — Retail trade of goods is tertiary activity.', 'TRUE — Distribution to customers is tertiary-sector activity.', 'FALSE — Retail and distribution of goods are tertiary even for physical products.', 'FALSE — Book-related services remain tertiary.'], '4/5', 25, 'full' ),
( '3.2', 'CASE 3.2.26', 'Well-being Correlation', 'Review GDP correlation with health and happiness indicators. Evaluate the following economic assertions:', ARRAY['GDP is often correlated with indicators such as health status and happiness.', 'Higher GDP frequently aligns with better health and happiness scores.', 'GDP critics still note correlation with some wellbeing measures.', 'Correlation implies GDP captures every aspect of wellbeing perfectly.', 'Cross-country data show no link between GDP and health outcomes.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Wealthier economies often report better health and happiness indicators on average.', 'TRUE — Rising GDP per capita commonly tracks improved wellbeing metrics in cross-country data.', 'TRUE — The text acknowledges correlation despite GDP limits.', 'FALSE — Correlation does not mean GDP fully measures welfare.', 'FALSE — GDP is usually correlated with wellbeing indicators.'], '3/5', 26, 'full' ),
( '3.2', 'CASE 3.2.27', 'Forestry and Furniture Plant', 'Consider a forestry concession supplies logs to a furniture plant finishing dining tables. Evaluate the following economic assertions:', ARRAY['The link illustrates primary output feeding secondary production.', 'Finishing tables for dining rooms is tertiary because buyers are households.', 'Furniture finishing is tertiary because it serves home customers.', 'Both stages are secondary because furniture is sold to households.', 'Logging and furniture making are both secondary because output is sold retail.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Primary extraction commonly supplies secondary manufacturers.', 'FALSE — Household buyers do not shift furniture making from secondary to tertiary.', 'FALSE — Table finishing at a plant is manufacturing, not a service to consumers.', 'FALSE — Logging is primary resource use; furniture making is a separate secondary stage.', 'FALSE — Retail sale of furniture does not reclassify logging as secondary activity.'], '3/5', 27, 'full' ),
( '3.2', 'CASE 3.2.28', 'Secondary Manufacturing Role', 'Review a manufacturer producing electronic components for industrial buyers. Evaluate the following economic assertions:', ARRAY['Client technical advice alongside fabrication does not remove secondary classification.', 'Manufactured components are secondary-sector output regardless of input origins.', 'Selling components to smartphone makers keeps fabrication in secondary manufacturing.', 'Transforming raw materials into finished components is secondary manufacturing.', 'The manufacturer is tertiary because it sells to smartphone makers, not final consumers.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Fabricating goods remains secondary even if advice accompanies sales.', 'TRUE — Manufactured components are secondary-sector output.', 'TRUE — Manufacturing for business customers remains secondary activity.', 'TRUE — Manufacturing components from materials is secondary activity.', 'FALSE — Selling to firms does not reclassify manufacturing as services.'], '1/5', 28, 'full' ),
( '3.2', 'CASE 3.2.29', 'Sector Assignment Traps', 'Review subtle sector misclassification traps. Evaluate the following economic assertions:', ARRAY['Retail distribution of finished goods belongs to the tertiary sector.', 'A software helpdesk is tertiary even when supporting manufactured devices.', 'Manufacturing and after-sales service mean the entire firm is tertiary.', 'Printing books and bookstore distribution are both secondary.', 'After-sales repair makes the entire firm tertiary only.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Distribution is a service activity within the tertiary sector.', 'TRUE — Technical support is a tertiary service.', 'FALSE — A firm may run secondary production and tertiary services simultaneously.', 'FALSE — Manufacturing and distribution occupy different sectors.', 'FALSE — After-sales repair is tertiary but does not erase manufacturing classification.'], '4/5', 29, 'full' ),
( '3.2', 'CASE 3.2.30', 'GDP Border Rule', 'Analyze the geographic rule for GDP measurement. Evaluate the following economic assertions:', ARRAY['GDP measures production within a country''s borders regardless of firm nationality.', 'Final goods produced domestically within a year enter GDP totals.', 'Output from a domestic plant of a foreign-owned firm counts in that country''s GDP.', 'Foreign production by domestic firms is counted where it occurs, not in home GDP.', 'Territorial production location determines GDP inclusion.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — National GDP counts output produced inside territorial borders.', 'TRUE — Domestic final production in the period is counted.', 'TRUE — Location of production determines GDP inclusion.', 'TRUE — Foreign production is counted where it occurs, not in home GDP.', 'TRUE — Geographic location of production determines which country records the output.'], '2/5', 30, 'full' ),
( '3.2', 'CASE 3.2.31', 'Quality of Growth Critique', 'Review limits of GDP regarding growth quality. Evaluate the following economic assertions:', ARRAY['Disaster rebuild spending can lift GDP without restoring lost wellbeing.', 'Quality concerns are part of why GDP use is debated.', 'GDP totals value produced without automatically distinguishing harmful from beneficial output.', 'GDP does not show whether growth improves environmental conditions.', 'Rising GDP necessarily proves growth is environmentally sustainable.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Measured output can rise while welfare remains impaired.', 'TRUE — Quality and sustainability are standard GDP criticisms.', 'TRUE — GDP totals value produced, not whether output is beneficial.', 'TRUE — GDP does not by itself show sustainability or quality.', 'FALSE — GDP does not by itself show sustainability or quality.'], '5/5', 31, 'full' ),
( '3.2', 'CASE 3.2.32', 'Banking as Tertiary', 'Review banking within the three-sector model. Evaluate the following economic assertions:', ARRAY['Banking branches providing loans are tertiary financial services.', 'Money used in banking is not classified as a natural resource making banking primary.', 'A national bank serving only home customers becomes secondary.', 'Insurance and banking both belong to the secondary sector.', 'Banking is secondary because it funds manufacturing clients.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Banking is classified within the tertiary sector.', 'TRUE — Banking is a financial service, not resource extraction.', 'FALSE — Financial services stay tertiary regardless of customer location.', 'FALSE — Financial services are tertiary activity.', 'FALSE — Financing manufacturers does not turn banking into manufacturing.'], '3/5', 32, 'full' ),
( '3.2', 'CASE 3.2.33', 'Shipbuilding Sector Type', 'Analyze how to classify shipyard activity in the three-sector model. Evaluate the following economic assertions:', ARRAY['Steel import storage and hull welding occupy different sectors.', 'Later cargo transport at sea does not reclassify shipbuilding as tertiary.', 'Port warehousing before welding is tertiary logistics.', 'Painting finished hulls for delivery remains secondary manufacturing support.', 'Welding hull sections from steel plate is secondary manufacturing.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Warehousing is tertiary; welding is secondary.', 'TRUE — Building ships is manufacturing, not service delivery.', 'TRUE — Storage before manufacturing is a tertiary service.', 'TRUE — Finishing manufactured vessels remains secondary activity.', 'TRUE — Building ships from materials is secondary activity.'], '2/5', 33, 'full' ),
( '3.2', 'CASE 3.2.34', 'Service Share Measurement', 'Analyze measuring tertiary share in total output. Evaluate the following economic assertions:', ARRAY['Advanced economies often see services dominate total output shares.', 'Tertiary share is measured separately from GDP totals.', 'Primary share above seventy percent typifies rich EU economies.', 'Service share alone identifies every firm''s sector classification.', 'Less developed economies typically show smaller primary shares than advanced EU states.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — High service shares show tertiary dominance in advanced economies.', 'FALSE — Sector shares are derived from GDP output breakdowns.', 'FALSE — High tertiary, not primary, shares typify advanced EU states.', 'FALSE — Aggregate shares differ from individual firm sector labels.', 'FALSE — Less developed countries depend more on primary activity.'], '4/5', 34, 'full' ),
( '3.2', 'CASE 3.2.35', 'GDP as an Economic Activity Indicator', 'Review GDP as an overall activity indicator. Evaluate the following economic assertions:', ARRAY['GDP per capita is commonly used as an indicator of living standards.', 'GDP does not replace all other indicators because it misses some income sources.', 'GDP counts final goods and services produced in a defined period.', 'GDP excludes final services such as insurance from its totals.', 'Insurance and other final services are omitted from official GDP totals.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — GDP per capita is linked to living standards.', 'TRUE — GDP misses some informal and unpaid activity.', 'TRUE — GDP covers final domestic production over time.', 'FALSE — Final insurance premiums and claims services enter GDP when produced domestically.', 'FALSE — Service-sector final output is included when it meets GDP boundary rules.'], '1/5', 35, 'full' ),
( '3.2', 'CASE 3.2.36', 'Retail Sector Trap', 'Review traps when classifying retail activity. Evaluate the following economic assertions:', ARRAY['A bookstore selling printed titles performs tertiary retail distribution.', 'Warehouse pick-and-pack for e-commerce orders is classified as a tertiary logistics activity.', 'Mixed manufacturing and retail in one firm can span secondary and tertiary activity.', 'Physical goods sold in shops do not automatically make retail secondary.', 'Printing the titles is secondary while selling them is tertiary.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Retail trade of goods is tertiary activity.', 'TRUE — Fulfilment services are tertiary activity.', 'TRUE — Mixed firms can span secondary production and tertiary retail.', 'TRUE — Distribution and retail are tertiary even for physical products.', 'TRUE — Manufacturing and retail occupy different sectors.'], '3/5', 36, 'full' ),
( '3.2', 'CASE 3.2.37', 'Software Support Sector Trap', 'Review sector traps around software support services. Evaluate the following economic assertions:', ARRAY['A small IT-support venture''s technical support is tertiary even when tied to refurbished goods.', 'Remote support abroad remains tertiary when produced domestically.', 'Software helpdesks troubleshooting networks provide tertiary services.', 'Writing code for clients is secondary manufacturing.', 'Support is secondary because computers are manufactured products.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Support services remain tertiary when linked to goods.', 'TRUE — Client location does not reclassify domestic tertiary services.', 'TRUE — Technical support is a tertiary service.', 'FALSE — Software services are tertiary in this context.', 'FALSE — Supporting devices is tertiary, not manufacturing.'], '5/5', 37, 'full' ),
( '3.2', 'CASE 3.2.38', 'Multi-sector Firms', 'Analyze firms operating across more than one sector. Evaluate the following economic assertions:', ARRAY['The three-sector model classifies activities rather than assigning one label per economy.', 'A farm selling produce can only be classified as primary.', 'A manufacturer that also gives client advice is tertiary only.', 'A single sector label on a firm blocks any activity in another sector.', 'One sector label applied to a firm prevents any activity in another sector.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — The model classifies activities, not single labels per economy.', 'FALSE — Mixed-sector firms may combine farming with processing or retail activities.', 'FALSE — Manufacturing can coexist with service offerings.', 'FALSE — Sector labels describe activities, not exclusive limits on what a firm may do.', 'FALSE — Classification by activity allows several sector types within one enterprise.'], '3/5', 38, 'full' ),
( '3.2', 'CASE 3.2.39', 'Output Share Shifts', 'Analyze how sector output shares shift with development. Evaluate the following economic assertions:', ARRAY['Emerging countries typically depend heavily on primary activity before tertiary dominance emerges.', 'Tertiary dominance in EU states coexists with some primary and secondary output.', 'Primary share often falls as countries become more developed.', 'Economic development advancing tends to raise relative tertiary output.', 'Secondary and tertiary shares must both fall as primary share falls.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Emerging economies typically depend heavily on primary activity first.', 'TRUE — Advanced economies still contain all sectors, with tertiary largest.', 'TRUE — Advanced economies rely less on primary output shares.', 'TRUE — More developed economies shift toward services.', 'FALSE — Development reallocates activity among sectors over time.'], '2/5', 39, 'full' ),
( '3.2', 'CASE 3.2.40', 'Standard of Living Link', 'Review linking GDP per capita to living standards. Evaluate the following economic assertions:', ARRAY['Living standards correlate with GDP though GDP misses some welfare dimensions.', 'Per capita averages miss distribution of income within a country.', 'GDP per capita fully captures inequality within a country.', 'Higher GDP per capita in EU members is unrelated to living standards.', 'Low GDP per capita alone defines an emerging economy''s entire sector mix.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Correlation exists despite GDP limits.', 'TRUE — Per capita averages miss distribution of income.', 'FALSE — Per capita averages miss distribution of income.', 'FALSE — GDP per capita is linked to living standards.', 'FALSE — Sector mix patterns are tendencies, not single indicators.'], '4/5', 40, 'full' ),
( '3.2', 'CASE 3.2.41', 'Classifying Industrial Fabrication', 'Analyze how to classify industrial fabrication in the sector model. Evaluate the following economic assertions:', ARRAY['Client advice alongside fabrication does not remove secondary classification.', 'Advice to clients converts fabrication into tertiary services only.', 'Buying mined metals as inputs turns factory fabrication into primary extraction.', 'Testing products in the factory becomes a tertiary inspection service only.', 'Buying mined materials for production does not move manufacturing from secondary to primary.'], ARRAY[true, false, false, false, true], ARRAY['TRUE — Manufacturing remains secondary even if services accompany sales.', 'FALSE — Manufacturing remains secondary even if services accompany sales.', 'FALSE — Component fabrication stays secondary whatever raw materials are purchased.', 'FALSE — Quality steps in manufacturing stay secondary activity.', 'TRUE — Input from mines does not change the secondary nature of manufacturing.'], '2/5', 41, 'full' ),
( '3.2', 'CASE 3.2.42', 'Insurance Sector Type', 'Review insurance within tertiary services. Evaluate the following economic assertions:', ARRAY['Insurance cooperatives processing claims provide tertiary services.', 'Underwriting and claims payment are tertiary financial services.', 'Claims handling is tertiary whether the client is a farm or a factory.', 'Insurance is primary because policies cover basic risks.', 'Insurance tied to manufactured goods becomes secondary.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Insurance is a financial service in the tertiary sector.', 'TRUE — Core insurance operations are tertiary activity.', 'TRUE — Insurance services are tertiary for all customer types.', 'FALSE — Risk coverage is a financial service, not resource extraction.', 'FALSE — Insurance remains tertiary regardless of what policies cover.'], '5/5', 42, 'full' ),
( '3.2', 'CASE 3.2.43', 'Clothing Production Sector', 'Analyze how to classify garment production and sales. Evaluate the following economic assertions:', ARRAY['Fashion retail selling finished jackets is tertiary trade.', 'Designing jackets can be tertiary while sewing them is secondary.', 'Imported fabric entering a sewing floor supports secondary manufacturing.', 'Sewing garments is secondary even when fashion is sold as a consumer experience.', 'Sewing jackets from imported fabric is secondary manufacturing.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Retail distribution is tertiary activity.', 'TRUE — Design services can be tertiary; sewing is manufacturing.', 'TRUE — Manufacturing uses imported materials in secondary production.', 'TRUE — Sewing garments is secondary manufacturing.', 'TRUE — Garment production from materials is secondary activity.'], '4/5', 43, 'full' ),
( '3.2', 'CASE 3.2.44', 'Coaching as Tertiary', 'Review coaching within the tertiary sector. Evaluate the following economic assertions:', ARRAY['Remote coaching sessions sold to clients are tertiary services.', 'Exporting coaching abroad keeps the activity tertiary.', 'Coaching combined with merchandise sales can still be tertiary service delivery.', 'Coaching studios renting space and paying trainers deliver tertiary services.', 'Designing training programmes is secondary manufacturing.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Coaching is a service classified in the tertiary sector.', 'TRUE — Client location does not reclassify domestic tertiary services.', 'TRUE — Core coaching remains tertiary even if goods are sold.', 'TRUE — Personal coaching is tertiary-sector activity.', 'FALSE — Design services are tertiary; book printing is secondary.'], '3/5', 44, 'full' ),
( '3.2', 'CASE 3.2.45', 'Distribution Services', 'Review distribution and logistics as tertiary activity. Evaluate the following economic assertions:', ARRAY['Picking and dispatching online orders from a warehouse belongs to tertiary logistics services.', 'Retail distribution of finished goods to shops is tertiary trade.', 'Warehousing is secondary because steel will be manufactured.', 'Bookstores are secondary because books are printed products.', 'Physical goods make distribution secondary manufacturing.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Fulfilment services are tertiary activity.', 'TRUE — Distribution to customers is tertiary-sector activity.', 'FALSE — Warehousing before manufacturing is tertiary logistics.', 'FALSE — Distribution to readers is tertiary activity.', 'FALSE — Distribution is tertiary even when goods are physical.'], '2/5', 45, 'full' ),
( '3.2', 'CASE 3.2.46', 'Raw Material Extraction', 'Analyze primary-sector extraction activities. Evaluate the following economic assertions:', ARRAY['Forestry supplying logs to mills is primary extraction.', 'Olive farms harvesting crops perform primary agricultural activity.', 'Farming, fishing, mining, and forestry extract raw materials in the primary sector.', 'Coal mining extracting ore is primary-sector activity.', 'Fishing becomes secondary once fish are filleted onboard.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Forestry extracts timber as a natural resource.', 'TRUE — Crop production is primary-sector activity.', 'TRUE — Primary activity extracts raw materials from the earth.', 'TRUE — Mining extracts raw materials and is primary activity.', 'FALSE — Extracting fish remains primary-sector activity.'], '4/5', 46, 'full' ),
( '3.2', 'CASE 3.2.47', 'Transforming Raw Materials', 'Review secondary-sector transformation. Evaluate the following economic assertions:', ARRAY['Timber mills exporting boards perform secondary processing of logs.', 'Fabricating industrial components is tertiary because components support services.', 'Sewing is tertiary because fashion is a consumer service.', 'Smelting remains primary because ore comes from mines.', 'Shipbuilding is tertiary because ships later carry cargo.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Milling logs into boards is secondary manufacturing.', 'FALSE — Manufacturing components is secondary activity.', 'FALSE — Sewing garments is secondary manufacturing.', 'FALSE — Processing ore or metal is secondary transformation.', 'FALSE — Building ships from materials is secondary manufacturing.'], '2/5', 47, 'full' ),
( '3.2', 'CASE 3.2.48', 'EU Tertiary Dominance', 'Review tertiary dominance in advanced EU economies. Evaluate the following economic assertions:', ARRAY['As economies develop, relative tertiary output tends to increase.', 'Higher GDP per capita in EU members links to high living standards in the model.', 'Primary food production dominates output in rich EU states.', 'High tertiary shares typify emerging economies with low GDP per capita.', 'Developed EU states keep primary output above seventy percent.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — More developed economies shift toward services in the three-sector model.', 'TRUE — GDP per capita is used as a living-standard indicator.', 'FALSE — Developed EU economies show tertiary dominance, not primary dominance.', 'FALSE — High tertiary shares characterise advanced, not emerging, economies.', 'FALSE — In developed EU countries the tertiary sector usually exceeds seventy percent.'], '5/5', 48, 'full' ),
( '3.2', 'CASE 3.2.49', 'Sector Trap Software Support', 'Review sector traps around software support. Evaluate the following economic assertions:', ARRAY['Refurbished-goods support from a small IT-support venture remains tertiary service activity.', 'Remote support to foreign clients remains tertiary.', 'Network troubleshooting by software helpdesks counts as tertiary service activity.', 'Manufacturing devices and supporting them can span secondary and tertiary activity.', 'Writing client software is tertiary service activity.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Support services remain tertiary when linked to goods.', 'TRUE — Client location does not reclassify domestic tertiary services.', 'TRUE — Technical support is a tertiary service.', 'TRUE — Manufacturing is secondary; support is tertiary alongside it.', 'TRUE — Software services are tertiary in this context.'], '1/5', 49, 'full' ),
( '3.2', 'CASE 3.2.50', 'Sector and GDP Synthesis', 'Review integrated sector and GDP claims. Evaluate the following economic assertions:', ARRAY['Emerging economies depend largely on primary activity while advanced EU states show tertiary dominance.', 'GDP measures final domestic production and supports growth comparisons when inflation-adjusted.', 'GDP critics note missing income, quality limits, and disaster rebuild effects.', 'GDP correlates perfectly with health and happiness in every case.', 'Manufacturing components and offering after-sales support collapse into a single tertiary label.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Development shifts sector shares toward services in rich economies.', 'TRUE — GDP totals final output; real growth uses adjusted figures.', 'TRUE — Standard criticisms include coverage, quality, and rebuild distortions.', 'FALSE — Correlation does not mean GDP fully measures welfare.', 'FALSE — Manufacturing stays secondary; support can be tertiary alongside it.'], '3/5', 50, 'full' ),
( '3.3', 'CASE 3.3.01', 'Profit-oriented Basics', 'Review how profit-oriented businesses relate revenues to costs and expenses. Evaluate the following economic assertions:', ARRAY['Strong customer demand alone guarantees profit regardless of expenses.', 'Break-even performance is the primary long-run goal of most profit-oriented manufacturers.', 'Recording revenue without controlling costs satisfies the profit objective.', 'Profit means matching expenses exactly while ignoring any surplus.', 'Covering costs alone is the usual long-run goal of profit-oriented manufacturers.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Rising costs can erase profit despite revenue.', 'FALSE — Profit-oriented firms seek surplus above break-even.', 'FALSE — Profit requires revenues to exceed costs, not revenue alone.', 'FALSE — Profit requires revenues to exceed costs and expenses.', 'FALSE — Profit-oriented firms aim for revenue above costs to grow and reward risk.'], '2/5', 1, 'full' ),
( '3.3', 'CASE 3.3.02', 'Bakery Oven Reinvestment', 'Consider a bakery chain targets revenue above costs to fund new ovens in a growing shop. Evaluate the following economic assertions:', ARRAY['Seeking revenue above costs to buy new ovens reflects profit-oriented reinvestment logic.', 'Retained surplus from profitable sales can finance equipment upgrades.', 'The shop treats higher revenue than expenses as the basis for buying new ovens.', 'Durability requires distributing all earnings immediately to owners.', 'Oven purchases must come from donations rather than business surplus.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Profit funds capital renewal in commercial firms.', 'TRUE — Profit enables reinvestment in commercial businesses.', 'TRUE — Profit orientation links surplus to reinvestment.', 'FALSE — Reinvestment also supports long-run business sustainability.', 'FALSE — Commercial firms reinvest profit into equipment.'], '2/5', 2, 'full' ),
( '3.3', 'CASE 3.3.03', 'Revenue versus Costs', 'Analyze the revenue-versus-cost relationship in profit orientation. Evaluate the following economic assertions:', ARRAY['Cost control matters because profit compares revenue with total expenses.', 'Commercial expansion often relies on profit rather than persistent losses.', 'Margin above break-even allows commercial firms to expand operations.', 'Profit emerges when revenue exceeds total costs in a period.', 'Profit orientation requires revenues to exceed costs and expenses.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Both revenue and costs determine profit outcomes.', 'TRUE — Commercial expansion relies on profit, not persistent losses.', 'TRUE — Surplus above costs supports growth in profit-oriented firms.', 'TRUE — Margin appears only when revenue exceeds costs.', 'TRUE — Profit means higher revenues than total costs.'], '4/5', 3, 'full' ),
( '3.3', 'CASE 3.3.04', 'Disaster Relief Funding', 'Consider a humanitarian NPO collecting donations before dispatching flood-relief kits to affected towns. Evaluate the following economic assertions:', ARRAY['Charging a cost-recovery fee for some supplies converts a humanitarian NPO into a profit-maximising firm.', 'Any surplus from donations can be reinvested into further relief work.', 'Not-for-profit status means the organisation may ignore funding entirely.', 'Dispatching kits without prior inflows is typical NPO practice.', 'Relief organisations need no inflows because volunteers supply everything.'], ARRAY[false, true, false, false, false], ARRAY['FALSE — Cost recovery does not redefine a humanitarian NPO as profit-oriented.', 'TRUE — NPO surpluses are typically reinvested into the mission.', 'FALSE — NPOs must still secure and manage revenues or donations.', 'FALSE — Relief delivery requires funding for materials and logistics.', 'FALSE — Humanitarian delivery requires funded materials and logistics.'], '3/5', 4, 'full' ),
( '3.3', 'CASE 3.3.05', 'Profit Reinvestment', 'Review reinvestment of profit in commercial firms. Evaluate the following economic assertions:', ARRAY['Profits can fund new equipment that improves future service capacity.', 'Retained profit can be reinvested to improve durability and sustainability of a business.', 'Reinvestment supports long-run survival alongside owner returns.', 'Repair shops reinvesting profit into diagnostic tools show commercial reinvestment.', 'Profit cannot fund equipment because it must be distributed immediately.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Reinvested profit supports capital renewal.', 'TRUE — Reinvested profit strengthens long-run business capacity.', 'TRUE — Reinvestment supports durability and future returns.', 'TRUE — Retained profit funds capital renewal in profit-oriented firms.', 'FALSE — Profits can be reinvested in the business.'], '5/5', 5, 'full' ),
( '3.3', 'CASE 3.3.06', 'Merchandise and Mission Funding', 'Consider a conservation NPO that sells branded merchandise and ploughs surplus into habitat protection. Evaluate the following economic assertions:', ARRAY['Selling merchandise can raise funds for habitat work within an NPO model.', 'Merchandise income helps cover operating costs while funding conservation work.', 'Habitat work funded from surplus proves the organisation maximises owner wealth.', 'A conservation NPO seeks maximum private owner wealth like a listed corporation.', 'A conservation NPO must distribute merchandise surplus as private shareholder dividends.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Trading can fund mission activities within an NPO.', 'TRUE — Trading can supplement donations to cover mission costs.', 'FALSE — Merchandising surpluses can fund mission work without implying owner profit-maximisation.', 'FALSE — A conservation NPO is mission-driven and not organised to maximise private owner wealth.', 'FALSE — NPO surpluses support mission reinvestment, not owner payouts.'], '2/5', 6, 'full' ),
( '3.3', 'CASE 3.3.07', 'Owner and Investor Reward', 'Review profit as reward for owners and investors. Evaluate the following economic assertions:', ARRAY['Investors treat retained profit as reward for capital placed at risk.', 'Owner return logic treats profit as payoff for committing capital to uncertain ventures.', 'Profit orientation excludes any return to owners because customers pay prices.', 'Profits reward owners and investors for the risk they have taken.', 'Owners deserve no return when revenues exceed expenses.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Profit compensates owners and investors for risk taken.', 'TRUE — Profit compensates owners for capital risk.', 'TRUE — Owners and investors expect reward when revenues exceed costs.', 'TRUE — Returns compensate capital providers for bearing business risk.', 'FALSE — Owners and investors expect profit as reward for risk.'], '4/5', 7, 'full' ),
( '3.3', 'CASE 3.3.08', 'Startup Founder Risk', 'Consider startup founders who expect profit as compensation for the risk they have invested. Evaluate the following economic assertions:', ARRAY['Investors bear no risk in startups because lenders absorb all uncertainty.', 'Startups are NPOs because early years may show low margins.', 'Covering costs fully removes any need to reward risk-bearing owners.', 'Profit has no connection to capital placed at risk.', 'Risk-bearing founders should expect no return when revenues exceed expenses.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Owners and investors bear risk rewarded by profit.', 'FALSE — Profit orientation depends on aims, not temporary margin levels.', 'FALSE — Founders seek surplus beyond break-even to reward risk.', 'FALSE — Profit compensates capital exposed to business risk.', 'FALSE — Founders and investors expect profit as reward for risk.'], '1/5', 8, 'full' ),
( '3.3', 'CASE 3.3.09', 'Not-for-Profit Organisation Aims', 'Analyze the main aim of not-for-profit organisations when they pursue a mission rather than owner profit. Evaluate the following economic assertions:', ARRAY['Mission delivery still requires enough inflows to finance operations.', 'Not-for-profit organisations pursue a social or environmental mission rather than owner profit-maximisation.', 'A surplus in an NPO is typically used to further the organisation''s purpose.', 'Humanitarian, conservation, and environmental campaign NPOs all pursue mission delivery rather than private profit.', 'Not-for-profit status means the organisation may ignore funding needs entirely.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — NPOs still need revenues or donations to operate.', 'TRUE — The defining aim is mission delivery, not owner profit.', 'TRUE — Surpluses typically return to the mission.', 'TRUE — Different mission types can still share NPO characteristics.', 'FALSE — NPOs must still fund staff, materials, and logistics.'], '5/5', 9, 'full' ),
( '3.3', 'CASE 3.3.10', 'Charity Clinic Cost Coverage', 'Consider a charity clinic bills insurers enough to cover running costs while treating patients. Evaluate the following economic assertions:', ARRAY['Surplus from billing can improve patient services rather than owner payouts.', 'Treating patients while covering costs shows mission delivery with financial discipline.', 'Billing insurers to cover running costs aligns with not-for-profit cost coverage.', 'Billing insurers converts the clinic into a listed corporation.', 'Community clinics prove NPOs never need to cover staff or supply costs.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — NPO surpluses reinvest in mission delivery.', 'TRUE — NPOs combine service delivery with cost coverage.', 'TRUE — NPOs seek to cover costs while delivering mission services.', 'FALSE — NPOs can bill for cost coverage without profit-maximising aims.', 'FALSE — NPO healthcare must cover operating costs.'], '3/5', 10, 'full' ),
( '3.3', 'CASE 3.3.11', 'Covering Costs in NPOs', 'Review cost coverage for not-for-profit organisations. Evaluate the following economic assertions:', ARRAY['NPOs ignore revenue because mission work is voluntary in nature.', 'Food banks track whether donations cover warehouse rent for ongoing operation.', 'Not-for-profit status does not prevent earning surplus reinvested for the mission.', 'Mission delivery requires no financial inflows once an NPO is registered.', 'Donor income frees an NPO from covering operating costs responsibly.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — NPOs still need inflows to operate.', 'TRUE — NPOs must ensure operating costs are covered.', 'TRUE — NPOs may earn surplus reinvested into mission activities.', 'FALSE — NPOs need revenues or donations to operate.', 'FALSE — NPOs still need enough revenue to cover costs.'], '3/5', 11, 'full' ),
( '3.3', 'CASE 3.3.12', 'NGO Theatre Ticket Surplus', 'Consider an NGO theatre sells tickets nightly and reinvests any surplus in outreach programmes. Evaluate the following economic assertions:', ARRAY['Ticket income covering nightly running costs lets performances continue.', 'Outreach funded from surplus shows mission reinvestment of NPO gains.', 'Performances require covered costs even when the mission is cultural outreach.', 'Reinvesting ticket surplus in outreach uses NPO gains for mission expansion.', 'The theatre combines earned ticket income with mission reinvestment aims.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Ticket receipts must at least cover nightly operating expenses to sustain shows.', 'TRUE — Reinvested surplus can broaden mission reach.', 'TRUE — Cultural missions still rely on revenue covering performance running costs.', 'TRUE — NPO surpluses fund expanded mission activities.', 'TRUE — NPOs may combine fees and mission surplus use.'], '3/5', 12, 'full' ),
( '3.3', 'CASE 3.3.13', 'Donations as Revenue', 'Review donations as revenue for non-profit organisations. Evaluate the following economic assertions:', ARRAY['Donor income supports campaigns when earned revenue is limited.', 'Mixed donations and fees cannot sustain an NPO because only one revenue source is allowed.', 'Prior surplus cannot fund later aid shipments for humanitarian organisations.', 'Humanitarian NGOs dispatch kits before any funding because urgency overrides finance.', 'Donor gifts remove any need for NPOs to cover operating costs responsibly.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Donations finance mission operations.', 'FALSE — NPOs may combine multiple inflow types.', 'FALSE — Surpluses and donations enable ongoing services.', 'FALSE — Even urgent relief requires funded materials and logistics.', 'FALSE — NPOs still need enough revenue to cover costs.'], '5/5', 13, 'full' ),
( '3.3', 'CASE 3.3.14', 'Investors and Retained Profit', 'Consider how investors treat retained profit as reward for capital placed at risk. Evaluate the following economic assertions:', ARRAY['Retained profit can reward investors for capital exposed to business risk.', 'Investors expect profit as compensation for capital committed to the firm.', 'Retained earnings and investor reward both link to business risk-bearing.', 'Fixed wages to investors replace profit regardless of business performance.', 'Capital at risk deserves no return when revenues exceed expenses.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Retained earnings reward shareholders for capital placed at business risk.', 'TRUE — Investors receive profit as reward for risk taken.', 'TRUE — Profit on retained funds compensates owners who bear uncertainty of operations.', 'TRUE — Profit rewards vary with business performance and risk.', 'FALSE — Owners and investors expect profit as reward for risk.'], '1/5', 14, 'full' ),
( '3.3', 'CASE 3.3.15', 'NPO Revenue Mix', 'Review how not-for-profit organisations finance their activities. Evaluate the following economic assertions:', ARRAY['Donations and membership fees can fund not-for-profit operations.', 'Trading surplus can support mission spending within an NPO model.', 'Not-for-profit organisations never generate any surplus by definition.', 'Mission spending can only be financed by government grants.', 'Any surplus must be paid out as dividends to private owners.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Donations and fees are common NPO inflows.', 'TRUE — Trading can support mission costs without turning the NPO into a profit-maximiser.', 'FALSE — NPOs may generate surplus; they reinvest it rather than maximise owner profit.', 'FALSE — Funding sources can include donations, fees, and trading.', 'FALSE — NPO surplus supports the mission, not private dividends.'], '4/5', 15, 'full' ),
( '3.3', 'CASE 3.3.16', 'Humanitarian NPO Characteristics', 'Review a humanitarian not-for-profit organisation as an economic actor. Evaluate the following economic assertions:', ARRAY['A humanitarian NPO kit dispatch requires prior inflows to fund materials and logistics.', 'Mission delivery, not private profit-maximisation, is the organisation''s primary aim.', 'A humanitarian NPO is legally the same as any listed for-profit corporation.', 'A humanitarian NPO operates without covering staff or warehouse costs.', 'Any surplus must be distributed as private shareholder dividends.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Aid delivery needs funded materials and logistics.', 'TRUE — NPOs pursue mission aims rather than owner profit.', 'FALSE — NPO legal purpose differs from profit-maximising corporations.', 'FALSE — Staff and facilities still require funding.', 'FALSE — Surpluses support mission reinvestment.'], '4/5', 16, 'full' ),
( '3.3', 'CASE 3.3.17', 'Food Bank Rent Tracking', 'Consider a food bank tracks whether donations cover warehouse rent for its depot. Evaluate the following economic assertions:', ARRAY['Donations can cover rent while the food bank pursues its mission.', 'Food banks need not track costs because storage is goodwill.', 'Volunteer labour alone removes all premises cost requirements.', 'Rent coverage is irrelevant to not-for-profit organisations.', 'Warehouse rent must be funded by shareholder dividends.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Donor income helps NPOs finance operating expenses.', 'FALSE — NPOs must ensure operating costs are covered.', 'FALSE — Premises and logistics still require funding.', 'FALSE — Covering costs is central to NPO operation.', 'FALSE — NPO costs are covered by donations and mission revenues.'], '1/5', 17, 'full' ),
( '3.3', 'CASE 3.3.18', 'Conservation NPO Characteristics', 'Review a conservation not-for-profit organisation as an economic actor. Evaluate the following economic assertions:', ARRAY['Trading merchandise can fund habitat work without making the organisation profit-oriented.', 'Habitat protection financed from surplus fits not-for-profit behaviour.', 'Trading merchandise converts a conservation NPO into a firm maximising owner profit.', 'A conservation NPO behaves like a listed corporation maximising private owner wealth.', 'Merchandise surplus must be paid as private shareholder dividends.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Mission-funded trading is compatible with NPO status.', 'TRUE — Mission reinvestment is core NPO behaviour.', 'FALSE — Mission use of trading income does not redefine the organisation as profit-maximising.', 'FALSE — A conservation NPO is mission-driven, not owner-wealth-maximising.', 'FALSE — NPO surplus supports the mission.'], '3/5', 18, 'full' ),
( '3.3', 'CASE 3.3.19', 'Environmental Campaign Spending', 'Consider how an environmental campaign NPO raises funds while limiting spending to mission delivery. Evaluate the following economic assertions:', ARRAY['Limiting spending to mission delivery fits not-for-profit behaviour.', 'Campaigns still depend on covering staff and logistics costs.', 'Fundraising for campaigns proves the organisation maximises private owner profit.', 'An environmental campaign NPO distributes surplus as owner dividends by definition.', 'Not-for-profit status removes any need for funding.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Mission-focused spending is characteristic of NPOs.', 'TRUE — Campaign delivery still has operating costs.', 'FALSE — Fundraising for a mission is not the same as owner profit-maximisation.', 'FALSE — NPO surplus is reinvested in the mission.', 'FALSE — NPOs still need inflows to operate.'], '5/5', 19, 'full' ),
( '3.3', 'CASE 3.3.20', 'Risk and Profit Link', 'Analyze the link between business risk and profit. Evaluate the following economic assertions:', ARRAY['Profit rewards owners and investors for risk they have taken.', 'Investors view profit as compensation for capital exposed to market risk.', 'Covering costs alone satisfies owner expectations for risk taken.', 'Founders bear no risk in startups because lenders absorb all uncertainty.', 'Customer payments mean owners should expect no return when revenues exceed costs.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Returns compensate capital providers for bearing business risk.', 'TRUE — Investors receive profit as reward for risk taken.', 'FALSE — Commercial firms target profit above costs to reward risk.', 'FALSE — Owners and investors bear risk rewarded by profit.', 'FALSE — Owners expect reward when revenues exceed costs.'], '2/5', 20, 'full' ),
( '3.3', 'CASE 3.3.21', 'Durability Through Reinvest', 'Review profit reinvestment and business durability. Evaluate the following economic assertions:', ARRAY['Immediate distribution of all profit is required for commercial durability.', 'Reinvested profit supports durability and sustainability of a business.', 'Long-run survival for most firms depends on achieving profitable operations over time.', 'Commercial operators reinvesting surplus improve long-run survival prospects.', 'Profit enhances sustainability when reinvested in equipment improving future capacity.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Reinvestment also supports durability.', 'TRUE — Reinvested profit strengthens the firm''s long-run capacity.', 'TRUE — Most businesses aim to make profit to thrive over time.', 'TRUE — Profit supports reinvestment and long-run survival.', 'TRUE — Reinvested profit strengthens durability.'], '5/5', 21, 'full' ),
( '3.3', 'CASE 3.3.22', 'NPO Mission versus Profit', 'Analyze differences between not-for-profit and profit-oriented organisations. Evaluate the following economic assertions:', ARRAY['Profit-oriented firms primarily seek owner returns, while NPOs primarily pursue a mission.', 'An NPO may earn a surplus and still remain not-for-profit if surplus serves the mission.', 'Any organisation that sells goods must be classified as profit-maximising.', 'NPOs never employ paid staff because volunteers cover all work.', 'Mission and surplus are mutually exclusive for every organisation.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — The core distinction is primary aim: profit versus mission.', 'TRUE — Surplus reinvested in the mission is compatible with NPO status.', 'FALSE — Trading does not automatically imply profit-maximisation.', 'FALSE — Many NPOs employ paid staff funded by inflows.', 'FALSE — NPOs can pursue a mission while managing a surplus.'], '2/5', 22, 'full' ),
( '3.3', 'CASE 3.3.23', 'Profit Motive Contrast', 'Review profit orientation with not-for-profit aims. Evaluate the following economic assertions:', ARRAY['NPOs may reinvest surplus into mission projects rather than owner payouts.', 'Commercial profit aims include rewarding owner risk and funding reinvestment.', 'Charging fees does not automatically make an organisation profit-oriented.', 'Profit-maximisation for owners is the primary NPO financial goal.', 'Both profit firms and NPOs ignore revenue because missions differ.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — NPO surpluses support mission reinvestment.', 'TRUE — Profit orientation includes surplus, reinvestment, and risk reward.', 'TRUE — Fee income can support NPO cost coverage without profit-maximisation.', 'FALSE — NPOs prioritise mission over owner profit-maximisation.', 'FALSE — Both need inflows to operate.'], '3/5', 23, 'full' ),
( '3.3', 'CASE 3.3.24', 'Surplus versus Profit Wording', 'Review surplus in NPOs compared with profit in firms. Evaluate the following economic assertions:', ARRAY['NPO surplus reinvested for mission resembles retained gain but not owner profit.', 'Owner dividends are typical for NPO surplus distribution.', 'Ticket surplus at an NGO theatre funds outreach instead of shareholder dividends.', 'Commercial profit and NPO surplus both involve inflows exceeding expenses when surplus arises.', 'Using surplus to improve services proves an NPO abandoned its mission.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — NPO surpluses fund mission activities rather than owner returns.', 'TRUE — NPO surpluses are reinvested, not owner dividends.', 'TRUE — NPO surplus supports mission reinvestment.', 'TRUE — Both involve revenues above costs when surplus arises.', 'FALSE — Improving services aligns with NPO aims.'], '4/5', 24, 'full' ),
( '3.3', 'CASE 3.3.25', 'Long-run Survival', 'Review long-run survival aims in businesses. Evaluate the following economic assertions:', ARRAY['Commercial firms typically aim for long-run operation by earning profit rather than merely breaking even.', 'Commercial durability excludes any retention of earnings.', 'Break-even alone is sufficient for most profit-oriented firms seeking to thrive.', 'Operating for longevity motivates seeking profit rather than only break-even.', 'Both firm types can ignore finance after the first successful year.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Profit supports long-run survival and growth.', 'FALSE — Retained profit supports long-run capacity.', 'FALSE — Profit-oriented businesses target revenue above costs.', 'FALSE — Profit supports long-run survival and reinvestment.', 'FALSE — Ongoing inflows remain necessary.'], '1/5', 25, 'full' ),
( '3.3', 'CASE 3.3.26', 'Investor Return Logic', 'Analyze investor expectations about profit returns. Evaluate the following economic assertions:', ARRAY['Investors in expanding firms view profit as compensation for capital exposed to market risk.', 'Retained profit must be unrelated to investor risk because it stays in the firm.', 'Commercial investors view break-even as the ideal long-run outcome.', 'Investors treat profit as a salary unrelated to capital committed to the firm.', 'Owner return logic rejects any link between profit and capital at risk.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Investors receive profit as reward for risk taken.', 'FALSE — Retained profit reflects returns on capital at risk.', 'FALSE — Investors typically expect profit above costs.', 'FALSE — Profit rewards capital providers for risk taken.', 'FALSE — Profit compensates owners for capital placed at risk.'], '3/5', 26, 'full' ),
( '3.3', 'CASE 3.3.27', 'NPO Mission Types', 'Review how different not-for-profit missions share the same economic logic. Evaluate the following economic assertions:', ARRAY['A conservation NPO illustrates environmental mission focus within an NPO model.', 'A humanitarian NPO illustrates humanitarian mission delivery within an NPO model.', 'An environmental campaign NPO illustrates a mission-driven non-profit organisation.', 'Different mission labels remove the shared need to fund operations.', 'Mission type alone turns an NPO into a profit-maximising corporation.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Conservation work can be organised as an NPO mission.', 'TRUE — Humanitarian delivery can be organised as an NPO mission.', 'TRUE — Campaign advocacy can be organised as an NPO mission.', 'FALSE — All NPOs still need resources to operate.', 'FALSE — Mission type does not redefine the organisation as profit-maximising.'], '5/5', 27, 'full' ),
( '3.3', 'CASE 3.3.28', 'Cost Coverage Threshold', 'Review covering costs as the NPO threshold. Evaluate the following economic assertions:', ARRAY['Covering costs allows NPOs to reinvest any surplus into mission activities.', 'Cost coverage allows NPOs to operate without donations or fees.', 'NPOs and commercial firms share identical primary goals for owner profit.', 'Clinics need no revenue because treatment is a mission service.', 'Maximising owner profit is the primary financial goal of not-for-profit organisations.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Surplus can be reinvested to enhance mission delivery.', 'TRUE — Inflows are still required to meet costs.', 'FALSE — Commercial firms target owner profit; NPOs focus on mission cost coverage.', 'FALSE — NPO healthcare must cover operating costs.', 'FALSE — NPOs prioritise mission cost coverage over owner profit.'], '2/5', 28, 'full' ),
( '3.3', 'CASE 3.3.29', 'Social Enterprise Cafe Margin', 'Consider a social enterprise cafe seeks a margin to open a second training kitchen. Evaluate the following economic assertions:', ARRAY['Achieving revenue above costs can finance additional mission capacity.', 'Seeking margin to fund a training kitchen targets surplus for mission-related expansion.', 'Mission-related expansion can be financed from earned margin above costs.', 'Seeking margin proves the cafe abandoned its social mission entirely.', 'The cafe treats surplus as fuel for a second training kitchen rather than owner dividends.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Margin above costs enables reinvestment.', 'TRUE — Surplus can fund expanded mission-related projects.', 'TRUE — Surplus above costs enables reinvestment.', 'TRUE — Margin can fund mission expansion within a social enterprise.', 'TRUE — Surplus can fund mission-related expansion.'], '3/5', 29, 'full' ),
( '3.3', 'CASE 3.3.30', 'Aid Packing and Prior Surplus', 'Consider how a humanitarian NPO uses prior-year donation surplus to pack aid parcels. Evaluate the following economic assertions:', ARRAY['Prior surplus can fund later aid shipments for humanitarian organisations.', 'Aid parcels reflect humanitarian mission delivery rather than owner profit-maximisation.', 'Using prior surplus for later aid proves the organisation maximises private owner wealth.', 'Humanitarian NPOs cannot retain unused funds from one period to the next.', 'Mission delivery requires no logistics funding if volunteers pack parcels.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Surpluses can be carried forward for mission use.', 'TRUE — Parcel packing serves the humanitarian mission.', 'FALSE — Mission use of surplus is not owner profit-maximisation.', 'FALSE — Unused inflows may be retained for later mission spending.', 'FALSE — Materials and logistics still require funded inputs.'], '2/5', 30, 'full' ),
( '3.3', 'CASE 3.3.31', 'Repair Shop Diagnostic Reinvest', 'Consider how founders of a repair shop reinvest last year''s profit into diagnostic tools. Evaluate the following economic assertions:', ARRAY['Founders treat retained profit as funding for long-run service capacity.', 'Diagnostic tool purchases from profit illustrate durability through reinvest.', 'Tool purchases must come from donations rather than business profit.', 'Reinvesting profit adopts not-for-profit dividend rules.', 'Repair shops must distribute all profit immediately to owners.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Retained profit strengthens durability.', 'TRUE — Reinvested profit strengthens long-run capacity.', 'FALSE — Commercial firms reinvest profit into equipment.', 'FALSE — Commercial reinvestment differs from NPO mission surplus use.', 'FALSE — Profits can be reinvested in the business.'], '5/5', 31, 'full' ),
( '3.3', 'CASE 3.3.32', 'Profit Trap: Revenue Alone', 'Review the trap that revenue alone equals profit. Evaluate the following economic assertions:', ARRAY['Profit compares total revenue with total costs and expenses.', 'Profit-oriented firms compare inflows with total expenses rather than counting revenue alone.', 'Margin appears only when revenue exceeds costs.', 'Strong sales do not guarantee profit when expenses rise faster than revenue.', 'Cost control remains essential to achieving profit.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Both sides of the account determine profit.', 'TRUE — Profit emerges only when total revenues exceed total expenses.', 'TRUE — A positive margin requires inflows to surpass combined operating costs.', 'TRUE — Rising costs can erase profit despite revenue.', 'TRUE — Both revenue and costs determine profit outcomes.'], '2/5', 32, 'full' ),
( '3.3', 'CASE 3.3.33', 'Mixed NPO Revenue', 'Analyze mixed funding sources for not-for-profit organisations. Evaluate the following economic assertions:', ARRAY['A conservation NPO combining merchandise sales and donations illustrates mixed NPO revenue.', 'Surplus at an environmental campaign NPO can support more campaigns rather than shareholder dividends.', 'Merchandise surplus at a conservation NPO can fund habitat work within the NPO model.', 'Mixed revenue automatically converts every NPO into a profit-maximising firm.', 'Donations alone are the only lawful NPO funding source.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — NPOs may combine donations and trading income.', 'TRUE — Mission reinvestment replaces owner dividends.', 'TRUE — Trading surplus can finance conservation work.', 'FALSE — Revenue mix does not redefine the primary NPO aim.', 'FALSE — Trading and fees can also fund NPO activity.'], '3/5', 33, 'full' ),
( '3.3', 'CASE 3.3.34', 'Reinvestment in NPO Services', 'Review reinvesting surplus to improve NPO services. Evaluate the following economic assertions:', ARRAY['Improved services require distributing surplus to private owners.', 'Clinic upgrades must be paid to external shareholders.', 'Spending surplus on better services shows an NPO failed to distribute donor funds.', 'Beneficiary gains prove the NPO switched to profit-maximisation.', 'Theatre outreach funded from surplus converts the NGO into a commercial cinema.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — NPO surplus reinvests in mission, not owner payouts.', 'FALSE — NPO surplus reinvests in mission activities.', 'FALSE — Improving services aligns with NPO aims.', 'FALSE — Service improvement aligns with mission reinvestment.', 'FALSE — Surplus can fund expanded outreach programmes.'], '4/5', 34, 'full' ),
( '3.3', 'CASE 3.3.35', 'Owner Risk Compensation', 'Review profit as compensation for owner risk. Evaluate the following economic assertions:', ARRAY['Profit returns reflect capital placed at risk in the venture.', 'Commercial owners expect some return when revenues exceed expenses.', 'Fixed salaries to investors replace profit regardless of business performance.', 'Higher revenue than expenses allows owners to be rewarded for risk-bearing.', 'Profit and capital risk-bearing are unrelated in all firms.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Profit compensates capital providers for risk taken.', 'TRUE — Owners and investors expect profit as reward for risk.', 'TRUE — Profit provides variable return linked to performance and risk.', 'TRUE — Profit orientation links surplus to owner and investor reward.', 'FALSE — Profit rewards capital placed at risk.'], '1/5', 35, 'full' ),
( '3.3', 'CASE 3.3.36', 'Operating for Longevity', 'Analyze operating over longer periods in both firm types. Evaluate the following economic assertions:', ARRAY['Most businesses aim to operate longer by earning profit rather than merely breaking even.', 'Commercial durability often relies on reinvested profit.', 'Mission organisations need ongoing cost coverage to continue delivery.', 'Profit above costs is irrelevant to commercial longevity.', 'Once established, both firm types can ignore finance after a successful year.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Profit supports long-run survival and growth.', 'TRUE — Reinvestment supports long-run commercial survival.', 'TRUE — NPOs require ongoing revenues to remain viable.', 'FALSE — Profit supports reinvestment and long-run survival.', 'FALSE — Ongoing inflows remain necessary.'], '4/5', 36, 'full' ),
( '3.3', 'CASE 3.3.37', 'NPO Examples Across Missions', 'Review shared characteristics of mission-driven not-for-profit organisations. Evaluate the following economic assertions:', ARRAY['Humanitarian, conservation, and environmental campaign organisations can all operate as NPOs.', 'Mission-driven organisations still face scarcity of funds and staff capacity.', 'NPO status abolishes all operating costs.', 'An NPO may ignore inflow management because there are never wages to pay.', 'Any organisation with a mission must be classified as primary-sector production.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Different missions can share not-for-profit organisation status.', 'TRUE — Scarcity still constrains NPO resources.', 'FALSE — NPOs still incur operating costs.', 'FALSE — Many NPOs employ staff and manage payroll.', 'FALSE — Sector classification depends on activity, not mission label alone.'], '3/5', 37, 'full' ),
( '3.3', 'CASE 3.3.38', 'Profit Enhances Sustainability', 'Review profit and commercial sustainability. Evaluate the following economic assertions:', ARRAY['Long-run commercial survival often depends on profitable operations over time.', 'Margin above break-even helps commercial firms expand and renew capital.', 'New ovens must be funded only by donations, not business profit.', 'Commercial sustainability requires distributing all earnings immediately.', 'Profit reduces sustainability because it always leaves firms underinvested.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Most businesses aim to make profit to thrive over time.', 'TRUE — Profit above costs enables reinvestment and growth.', 'FALSE — Commercial firms reinvest profit into equipment.', 'FALSE — Reinvestment also supports sustainability.', 'FALSE — Reinvestment supports long-run capacity.'], '2/5', 38, 'full' ),
( '3.3', 'CASE 3.3.39', 'Donor Income Role', 'Review donor income in NPO financing. Evaluate the following economic assertions:', ARRAY['Humanitarian relief depends on donations alongside any earned income.', 'Mixed donations and fees cannot sustain an NPO.', 'Donor income replaces all need for earned revenue at NPOs.', 'Donor income eliminates cost coverage discipline.', 'Food banks need not track costs when donations arrive.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Donations are essential revenue for many NPOs.', 'FALSE — NPOs may combine multiple inflow types.', 'FALSE — NPOs may combine donations with fees and other inflows.', 'FALSE — NPOs must still manage costs responsibly.', 'FALSE — NPOs must ensure operating costs are covered.'], '5/5', 39, 'full' ),
( '3.3', 'CASE 3.3.40', 'Service Enhancement Surplus', 'Analyze using NPO surplus to enhance services. Evaluate the following economic assertions:', ARRAY['Beneficiaries gain when surplus funds improved outreach or care.', 'Ticket surplus at an NGO theatre can fund outreach programmes.', 'Using surplus to improve beneficiary services aligns with NPO aims.', 'Clinic service upgrades from surplus reflect mission reinvestment.', 'Service enhancement surplus must be paid to external shareholders.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Mission reinvestment can broaden or improve services.', 'TRUE — Surplus can fund expanded outreach programmes.', 'TRUE — Reinvested surplus can enhance services for customers.', 'TRUE — Surplus can improve mission delivery quality.', 'TRUE — NPO surplus reinvests in mission activities.'], '3/5', 40, 'full' ),
( '3.3', 'CASE 3.3.41', 'Community Clinic NPO', 'Review community clinic behaviour as not-for-profit. Evaluate the following economic assertions:', ARRAY['Treating patients can continue only when operating costs are covered.', 'Community clinics pursuing cost coverage while treating patients reflect NPO priorities.', 'Community clinics distribute dividends like corporations.', 'Any clinic surplus should improve patient services rather than owner payouts.', 'Billing insurers proves maximising owner profit like a corporation.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — NPO healthcare must cover operating costs.', 'TRUE — NPO healthcare aims to cover costs while serving patients.', 'TRUE — NPO surpluses are not owner dividends.', 'TRUE — NPO surpluses reinvest in mission delivery.', 'FALSE — Covering costs differs from profit-maximisation for owners.'], '4/5', 41, 'full' ),
( '3.3', 'CASE 3.3.42', 'Disaster Relief Funding', 'Review funding humanitarian disaster relief. Evaluate the following economic assertions:', ARRAY['Relief organisations need secured funding before dispatching kits to disaster zones.', 'Prior surplus can complement donations for later relief operations.', 'Collecting donations before dispatch illustrates prior funding need for relief.', 'Disaster urgency bypasses all cost coverage requirements.', 'Volunteers remove all material costs from relief kits.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — NPOs need resources to deliver goods and services.', 'TRUE — Prior surpluses and donations enable ongoing services.', 'TRUE — Relief delivery requires secured inflows.', 'FALSE — Funding remains necessary even in urgent relief.', 'FALSE — Humanitarian delivery requires funded materials and logistics.'], '2/5', 42, 'full' ),
( '3.3', 'CASE 3.3.43', 'Margin Above Expenses', 'Analyze commercial margin above expenses. Evaluate the following economic assertions:', ARRAY['Margin above expenses funds new equipment in profit-oriented firms.', 'Profit requires comparing revenue with total costs.', 'Break-even matching is sufficient for commercial firms seeking to thrive.', 'Surplus above costs can support owner reward for risk-bearing.', 'Commercial firms target revenue above costs to reward risk and reinvest.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Profit funds reinvestment such as new equipment.', 'TRUE — Profit emerges when revenue exceeds costs.', 'TRUE — Profit-oriented firms target surplus above costs.', 'TRUE — Profit rewards owners for bearing business risk.', 'TRUE — Profit-oriented firms seek surplus above costs.'], '1/5', 43, 'full' ),
( '3.3', 'CASE 3.3.44', 'Break-even versus Thrive', 'Review break-even with thriving commercially. Evaluate the following economic assertions:', ARRAY['Break-even alone is insufficient for most profit-oriented firms seeking to thrive.', 'Longevity requires only break-even in profit-oriented firms.', 'Commercial thrive logic rejects any surplus above costs.', 'Thriving requires NPOs to maximise dividends to investors.', 'Retailers expand while keeping revenues below operating costs.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Commercial firms target profit above mere cost coverage.', 'FALSE — Profit supports long-run survival and growth.', 'FALSE — Profit-oriented firms target revenue above costs.', 'FALSE — NPOs aim to cover costs and reinvest surplus for the mission.', 'FALSE — Commercial expansion relies on profit.'], '5/5', 44, 'full' ),
( '3.3', 'CASE 3.3.45', 'Surplus Not Distributed', 'Analyze why NPO surplus is not distributed to owners. Evaluate the following economic assertions:', ARRAY['Commercial profit and NPO surplus follow different uses above costs.', 'NPO surplus is reinvested for mission rather than paid as owner dividends.', 'Ticket income must be profit distributed to owners.', 'Undistributed surplus proves the NPO failed financially.', 'Mission reinvestment is forbidden when an NPO earns surplus.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — NPO surpluses reinvest in mission; commercial profit may reward owners.', 'TRUE — NPO surpluses support mission, not owner payouts.', 'FALSE — Ticket revenue may fund mission reinvestment.', 'FALSE — Reinvested surplus broadens mission capacity.', 'FALSE — NPO surpluses are typically reinvested into the mission.'], '2/5', 45, 'full' ),
( '3.3', 'CASE 3.3.46', 'Commercial Durability Logic', 'Review commercial durability through profit. Evaluate the following economic assertions:', ARRAY['Long-run survival for most firms depends on profitable operations.', 'Retained profit supports renewal of tools, premises, or systems over time.', 'Profit enables reinvestment that supports commercial durability.', 'Commercial firms thrive long term by merely matching costs with no margin.', 'Bakeries funding new ovens from surplus illustrate commercial durability logic.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Most businesses aim to make profit to thrive over time.', 'TRUE — Retained profit funds capital renewal.', 'TRUE — Reinvested profit strengthens long-run capacity.', 'TRUE — Profit-oriented firms target revenue above costs.', 'TRUE — Profit funds capital renewal in commercial firms.'], '4/5', 46, 'full' ),
( '3.3', 'CASE 3.3.47', 'NGO Project Funding', 'Review funding NGO projects over time. Evaluate the following economic assertions:', ARRAY['Prior fundraising surplus can fund later NGO projects.', 'Mixed inflows must be paid out as owner dividends.', 'Project funding ignores operating costs because missions are voluntary.', 'Grant awards are ceremonial and require no cost coverage.', 'Volunteer recruitment removes all revenue requirements.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Prior surpluses and donations can fund later projects.', 'FALSE — NPOs combine inflows to cover mission costs.', 'FALSE — Projects require financed staff and materials.', 'FALSE — Grants must cover real project and staff costs.', 'FALSE — Operations still require funded inflows.'], '3/5', 47, 'full' ),
( '3.3', 'CASE 3.3.48', 'Profit and Capital Renewal', 'Review profit funding capital renewal. Evaluate the following economic assertions:', ARRAY['Owners may reinvest rather than withdraw all profit in a growing repair shop.', 'Capital renewal in commercial firms commonly draws on retained profit.', 'Renewal spending and profit orientation are linked in commercial firms.', 'Reinvesting profit into tools improves future production or service capacity.', 'Commercial profit must be distributed immediately and cannot fund new equipment.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Profits can be reinvested in the business.', 'TRUE — Commercial firms reinvest profit into equipment.', 'TRUE — Profit commonly funds reinvestment in commercial firms.', 'TRUE — Reinvested profit strengthens capacity.', 'FALSE — Profits can be reinvested in the business.'], '1/5', 48, 'full' ),
( '3.3', 'CASE 3.3.49', 'Funding Disaster Relief', 'Review funding humanitarian disaster relief. Evaluate the following economic assertions:', ARRAY['Disaster relief requires funding for materials, transport, and staff or volunteers'' support costs.', 'Surplus from earlier fundraising can finance later shipments.', 'Not-for-profit status removes the need for any inflow planning.', 'Relief can be delivered indefinitely without donations or other inflows.', 'Any surplus in relief work must become private owner profit.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Logistics and materials must be funded.', 'TRUE — Prior surplus can support later mission delivery.', 'FALSE — NPOs still plan and manage funding.', 'FALSE — Continuous delivery needs ongoing inflows.', 'FALSE — Mission surplus is not private owner profit.'], '2/5', 49, 'full' ),
( '3.3', 'CASE 3.3.50', 'NPO Synthesis', 'Review core claims about not-for-profit organisations. Evaluate the following economic assertions:', ARRAY['NPOs pursue a mission rather than maximising private owner profit.', 'Surpluses in NPOs typically return to mission delivery.', 'Humanitarian, conservation, and environmental campaign groups can illustrate NPO forms.', 'Selling goods always converts an NPO into a profit-maximising corporation.', 'NPOs can operate indefinitely with no inflows of any kind.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Mission aim distinguishes NPOs from profit-oriented firms.', 'TRUE — Mission reinvestment of surplus is standard NPO behaviour.', 'TRUE — Different mission types can share NPO characteristics.', 'FALSE — Trading for mission funding does not redefine the organisation as profit-maximising.', 'FALSE — Operations require donations, fees, grants, or trading income.'], '5/5', 50, 'full' ),
( '3.4', 'CASE 3.4.01', 'EU micro staff ceiling', 'Consider a workshop that employs nine people with €1.8m turnover. Evaluate the following economic assertions:', ARRAY['Because staff are below ten, a firm remains a micro enterprise despite turnover above €2m.', 'Forty-five staff alone guarantees small classification even if turnover exceeds €10m.', 'Meeting the staff ceiling alone is sufficient for micro status regardless of turnover or balance sheet totals.', 'Under the EU definition, a micro enterprise may employ fewer than ten people.', 'A firm qualifies as micro because its balance sheet is below €2m, regardless of turnover above €2m.'], ARRAY[false, false, false, true, false], ARRAY['FALSE — Both staff and financial thresholds must be met; high turnover can exclude micro status.', 'FALSE — Both staff and turnover thresholds must be satisfied for small status.', 'FALSE — Micro status requires both the staff ceiling and a turnover or balance sheet cap.', 'TRUE — EU micro classification requires fewer than ten employees.', 'FALSE — Turnover above €2m can disqualify micro status despite a qualifying balance sheet.'], '4/5', 1, 'full' ),
( '3.4', 'CASE 3.4.02', 'Micro turnover edge case', 'Consider a neighbourhood bakery, which has six staff and €2.1m turnover. Evaluate the following economic assertions:', ARRAY['Turnover above €10m can push a firm out of the small category even when staff remain below fifty.', 'Micro status allows either turnover up to €2m or a balance sheet total up to €2m alongside the staff limit.', 'Exceeding the €2m turnover cap can disqualify a firm from micro status even when staff are below ten.', 'Small status also requires turnover not exceeding €10m.', 'A small enterprise may employ fewer than fifty people under EU definitions.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — The €10m turnover cap is binding alongside the staff threshold.', 'TRUE — Micro firms must meet the staff cap and either the turnover or balance sheet financial ceiling.', 'TRUE — Turnover above €2m breaks the micro financial cap even with a small workforce.', 'TRUE — Small classification additionally requires turnover at or below €10m.', 'TRUE — The EU small category sets an upper staff limit below fifty employees.'], '5/5', 2, 'full' ),
( '3.4', 'CASE 3.4.03', 'Micro balance sheet OR test', 'Consider a design studio that reports eight staff, €2.4m turnover, and a €1.7m balance sheet. Evaluate the following economic assertions:', ARRAY['A firm fails the medium test because both financial figures must be below their respective caps.', 'Medium enterprises employ fewer than two hundred and fifty people under EU definitions.', 'Because turnover is within €50m, balance sheet size is irrelevant for medium classification.', 'Two hundred and forty employees exceed the medium staff ceiling.', 'Thirty-eight staff alone keeps a firm in the small category despite turnover above €10m.'], ARRAY[false, true, false, false, false], ARRAY['FALSE — Only one financial threshold needs to be met alongside staff; both need not pass.', 'TRUE — EU medium enterprises must employ fewer than 250 people.', 'FALSE — Exceeding the balance sheet cap disqualifies medium status even if turnover qualifies.', 'FALSE — 240 is below 250 and therefore within the medium staff limit.', 'FALSE — Small status requires both staff and turnover limits; breaching turnover removes small classification.'], '5/5', 3, 'full' ),
( '3.4', 'CASE 3.4.04', 'Small dual thresholds', 'Analyze EU small-enterprise criteria for a firm with forty-five staff and €9.5m turnover. Evaluate the following economic assertions:', ARRAY['MSME excludes micro firms and covers only small and medium categories.', 'SMEs represent a narrow minority of EU firms because large corporations dominate registration statistics.', 'SME labels are purely descriptive and have no effect on access to finance or reporting rules.', 'A components manufacturer counts as a medium enterprise because it operates internationally.', 'Medium status permits turnover up to €50m or a balance sheet total up to €43m together with the staff cap.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Micro firms are explicitly included in MSME/SME groupings.', 'FALSE — SMEs form the vast majority, not a minority, of EU businesses.', 'FALSE — Definitions actively shape finance access and regulatory treatment.', 'FALSE — Medium status depends on thresholds, not on geographic scope alone.', 'TRUE — Medium classification uses staff plus either turnover or balance sheet financial ceilings.'], '3/5', 4, 'full' ),
( '3.4', 'CASE 3.4.05', 'Small turnover breach', 'Consider a wholesaler that has thirty-eight staff but €10.4m turnover. Evaluate the following economic assertions:', ARRAY['A workforce of about ten thousand places a components manufacturer outside EU medium enterprise limits.', 'Approximately ninety-nine percent of businesses in the EU are SMEs.', 'Accounting requirements are identical for micro firms and large multinationals under EU practice.', 'Two hundred employees fall within the medium staff threshold.', 'Seven staff and a €1.9m balance sheet guarantee micro status despite turnover above €2m.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Ten thousand staff far exceeds the 250-employee medium ceiling.', 'TRUE — Official EU data cite that about 99% of EU businesses are SMEs.', 'FALSE — Size affects accounting rules, implying differences by category.', 'TRUE — 200 is below the 250-person medium limit.', 'FALSE — Exceeding the turnover cap disqualifies micro status even with qualifying staff and balance sheet.'], '4/5', 5, 'full' ),
( '3.4', 'CASE 3.4.06', 'Medium staff limit', 'Analyze medium-enterprise criteria for a manufacturer with two hundred and forty employees. Evaluate the following economic assertions:', ARRAY['Official SME classification can determine eligibility for EU support programmes and finance schemes.', 'Size definitions matter because accounting rules may differ for smaller and larger firms.', 'Ten employees still count as micro because the threshold says fewer than ten.', 'Two hundred and fifty employees satisfies the medium requirement of fewer than two hundred and fifty.', 'Fifty employees meets the small enterprise staff requirement of fewer than fifty.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — EU support and finance often hinge on meeting SME criteria.', 'TRUE — Size classification affects which accounting rules apply to a firm.', 'FALSE — Ten employees is not fewer than ten, so the staff test fails.', 'FALSE — 250 is not fewer than 250; the staff test fails.', 'FALSE — Small requires fewer than fifty staff; fifty is not eligible.'], '4/5', 6, 'full' ),
( '3.4', 'CASE 3.4.07', 'Medium financial OR logic', 'Consider a firm that has one hundred eighty staff, €48m turnover, and a €44m balance sheet. Evaluate the following economic assertions:', ARRAY['Any firm with more than ten employees is classified as large under EU rules.', 'MSME commonly groups micro, small, and medium enterprises under one umbrella term.', 'Crossing size thresholds can change which accounting rules apply to a business.', 'Any local shop qualifies as micro without reference to staff or turnover data.', 'Exactly ten staff exceeds the micro employee ceiling of fewer than ten.'], ARRAY[false, true, true, false, true], ARRAY['FALSE — Small and medium tiers cover firms well above ten employees.', 'TRUE — MSME refers to micro, small, and medium enterprises collectively.', 'TRUE — Growing beyond thresholds can shift reporting requirements.', 'FALSE — Official staff and financial tests determine micro status.', 'TRUE — The micro limit is strictly below ten employees; ten does not qualify.'], '5/5', 7, 'full' ),
( '3.4', 'CASE 3.4.08', 'Medium turnover within cap', 'Analyze an engineering firm has two hundred staff, €49m turnover, and a €42m balance sheet. Evaluate the following economic assertions:', ARRAY['Exceeding medium staff or financial thresholds generally moves a firm out of SME status.', 'Grant schemes often require proof that the applicant meets official micro enterprise criteria.', 'Exactly fifty staff exceeds the small category employee limit.', 'Micro firms must meet the staff cap and either the turnover or balance sheet financial limit.', 'Exactly 250 staff exceeds the medium employee ceiling.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Surpassing medium criteria places a firm in the large category.', 'TRUE — Support programmes use the standard EU micro thresholds for eligibility.', 'TRUE — The small staff cap is strictly below fifty employees.', 'TRUE — EU micro rules pair staff with one of two financial caps.', 'TRUE — The medium cap excludes firms with 250 or more employees.'], '3/5', 8, 'full' ),
( '3.4', 'CASE 3.4.09', 'A components manufacturer large scale', 'Consider a components manufacturer employs roughly ten thousand staff worldwide. Evaluate the following economic assertions:', ARRAY['A balance sheet above €43m can disqualify medium status even with low turnover.', 'Crossing micro limits while staying within small thresholds reclassifies the firm as small.', 'Policies supporting SMEs affect the vast majority of EU businesses by number.', 'Size differences can mean different accounting rule sets for a micro supplier and a components manufacturer.', 'Small enterprises must record turnover not exceeding €10m.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — The €43m balance sheet limit is binding for medium classification.', 'TRUE — Qualifying within small limits replaces micro status.', 'TRUE — With ~99% SME share, SME-focused policy reaches most businesses.', 'TRUE — Size classification links to differing accounting rules between micro and large firms.', 'TRUE — €10m is the small turnover ceiling in the EU table.'], '2/5', 9, 'full' ),
( '3.4', 'CASE 3.4.10', 'SME share in the EU', 'Analyze statements about the prevalence of SMEs in the European Union. Evaluate the following economic assertions:', ARRAY['Medium enterprises may report turnover up to €50m under EU definitions.', 'Micro classification requires both turnover and balance sheet to stay below €2m simultaneously.', 'Micro requires fewer than ten staff plus financial caps, stricter than small staff limits.', 'Small firms may report turnover up to €50m provided staff are below fifty.', 'Medium status is confirmed because staff and turnover both qualify despite balance sheet breach.'], ARRAY[true, false, true, false, false], ARRAY['TRUE — €50m is the medium turnover ceiling in the EU table.', 'FALSE — Only one financial measure must qualify, not both at once.', 'TRUE — Micro staff cap is below ten, much tighter than small''s below fifty.', 'FALSE — €50m is the medium turnover cap, not the small cap.', 'FALSE — Exceeding the balance sheet cap blocks medium status despite qualifying staff and turnover.'], '2/5', 10, 'full' ),
( '3.4', 'CASE 3.4.11', 'Why definitions matter', 'Analyze a startup seeks EU-backed finance tied to official size categories. Evaluate the following economic assertions:', ARRAY['Two people employed falls well within the micro staff ceiling.', 'Because SMEs are numerous, individual SME failures have no community impact.', 'Lenders may verify SME status using official headcount and turnover thresholds.', 'SME tiers require joint satisfaction of staff and relevant financial thresholds.', 'Most EU businesses by count are classified within SME size bands.'], ARRAY[true, false, true, true, true], ARRAY['TRUE — Two employees is below the ten-person micro limit.', 'FALSE — SME failures can still affect employees, suppliers, and local communities.', 'TRUE — Finance programmes rely on standard SME criteria.', 'TRUE — EU definitions combine staff with financial caps for each tier.', 'TRUE — ~99% of EU businesses are SMEs by count.'], '3/5', 11, 'full' ),
( '3.4', 'CASE 3.4.12', 'MSME terminology', 'Analyze terminology linking micro, small, and medium enterprises in EU policy. Evaluate the following economic assertions:', ARRAY['Turnover above €50m disqualifies medium status even if balance sheet qualifies.', 'Medium turnover cap is €10m, identical to the small limit.', 'Any firm with forty staff is micro because it employs fewer than fifty people.', 'Adding staff and sales can leave a firm classified as micro even after crossing small thresholds.', 'All EU firms file identical full public accounts regardless of size category.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — €52m turnover exceeds the €50m medium ceiling.', 'FALSE — €10m is the small cap; medium allows up to €50m.', 'FALSE — Forty staff exceeds micro limits and aligns with small staff range instead.', 'FALSE — Exceeding micro thresholds moves classification upward if small criteria are met.', 'FALSE — SME and large firms face different reporting expectations.'], '2/5', 12, 'full' ),
( '3.4', 'CASE 3.4.13', 'Accounting rules by size', 'Analyze a growing firm approaches medium thresholds. Evaluate the following economic assertions:', ARRAY['A small IT-support venture illustrate micro-scale operations compared with a components manufacturer''s large workforce.', 'Complete staff and financial data are needed to verify micro or other SME tiers.', 'SME definitions are irrelevant once a firm exports outside the home country.', 'One hundred and eighty employees fits the medium staff band if financial tests also pass.', 'Micro pairs sub-ten staff with €2m turnover or balance sheet limits.'], ARRAY[true, true, false, true, true], ARRAY['TRUE — Local micro ventures contrast with a components manufacturer''s large-scale workforce.', 'TRUE — Both staff and financial caps must be checked.', 'FALSE — Export activity does not override SME threshold tests.', 'TRUE — 180 is within medium''s below-250 staff range.', 'TRUE — This matches the EU micro row in the official SME table.'], '3/5', 13, 'full' ),
( '3.4', 'CASE 3.4.14', 'Micro balance within cap', 'Consider a consultancy that has seven staff, €2.3m turnover, and a €1.9m balance sheet. Evaluate the following economic assertions:', ARRAY['Operating alone prevents micro classification because micro requires at least five staff.', 'Large firms like a components manufacturer can employ thousands despite being few in number.', 'Three thousand staff can still fall within medium limits if turnover is managed.', 'Turnover within €10m alone makes a firm small even with three hundred employees.', 'Turnover above €50m prevents medium classification when that cap is breached.'], ARRAY[false, true, false, false, true], ARRAY['FALSE — There is no minimum staff count for micro beyond the upper cap.', 'TRUE — a components manufacturer illustrates large-scale employment in a rare large firm.', 'FALSE — 3,000 far exceeds the 250-employee medium cap.', 'FALSE — Three hundred staff exceeds medium limits regardless of turnover.', 'TRUE — €55m exceeds the €50m medium turnover limit.'], '5/5', 14, 'full' ),
( '3.4', 'CASE 3.4.15', 'Ten employees boundary', 'Consider a family firm that employs exactly ten people with €1.5m turnover. Evaluate the following economic assertions:', ARRAY['Micro enterprises form a large part of the SME group that dominates EU business counts.', '€43m is the medium balance sheet ceiling paired with sub-250 staff.', 'Nine staff and a €1.6m balance sheet confirm micro status despite €2.05m turnover.', 'Eight staff is compatible with micro but financial figures must still be verified.', 'The ninety-nine percent statistic proves SMEs generate ninety-nine percent of EU GDP.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Micro firms are part of the ~99% SME majority.', 'TRUE — €43m balance sheet is the medium cap in the EU table.', 'FALSE — Turnover above €2m disqualifies micro status even with qualifying balance sheet.', 'TRUE — Eight staff fits micro range pending financial tests.', 'FALSE — The figure refers to business numbers, not GDP share.'], '5/5', 15, 'full' ),
( '3.4', 'CASE 3.4.16', 'Fifty staff boundary', 'Analyze a logistics company employs exactly fifty people with €8m turnover. Evaluate the following economic assertions:', ARRAY['Leaving SME status can end eligibility for certain EU SME finance programmes.', 'Medium status holds because balance sheet is within €43m despite turnover above €50m.', 'Medium pairs sub-250 staff with a €10m turnover cap.', 'Thirty staff is within the small enterprise employee limit.', 'One hundred and eighty staff keeps a firm in the small category because turnover is below €50m.'], ARRAY[true, false, false, true, false], ARRAY['TRUE — SME-tied support typically excludes large firms.', 'FALSE — Exceeding turnover cap blocks medium status despite balance sheet within limits.', 'FALSE — €10m is the small turnover cap, not medium.', 'TRUE — 30 is below the fifty-employee small cap.', 'FALSE — 180 staff exceeds small''s below-fifty limit.'], '5/5', 16, 'full' ),
( '3.4', 'CASE 3.4.17', 'Two hundred fifty staff cap', 'Analyze a textile plant employs exactly two hundred fifty workers with €40m turnover. Evaluate the following economic assertions:', ARRAY['EU SME tiers combine employee ceilings with turnover and/or balance sheet caps.', 'Nine staff alone proves micro status without financial documentation.', 'A components manufacturer counts as a micro enterprise because it supplies components to phone makers.', 'One hundred and twenty-five staff satisfies the medium employee threshold.', 'Staff headcount must be verified alongside turnover for medium classification.'], ARRAY[true, false, false, true, true], ARRAY['TRUE — Combined criteria define each tier in the EU table.', 'FALSE — Financial thresholds are mandatory for micro confirmation.', 'FALSE — Supplier role does not determine size; headcount and financials do.', 'TRUE — 125 is below 250 staff limit.', 'TRUE — Staff verification is mandatory alongside turnover.'], '5/5', 17, 'full' ),
( '3.4', 'CASE 3.4.18', 'Large versus SME cut-off', 'Analyze when a firm is treated as large rather than SME under EU thresholds. Evaluate the following economic assertions:', ARRAY['Four employees fall within the micro staff ceiling.', '€2m turnover cap applies to small enterprises rather than micro.', '€55m turnover confirms medium status because balance sheet is below €43m.', 'Because SMEs are ninety-nine percent of firms, large firms employ fewer than one percent of workers.', 'A firm can progress from micro to small to medium as metrics cross successive thresholds.'], ARRAY[true, false, false, false, true], ARRAY['TRUE — Four staff is below ten-employee micro limit.', 'FALSE — €2m turnover cap applies to micro, not small.', 'FALSE — Turnover breach blocks medium status despite balance sheet within cap.', 'FALSE — Few large firms can still account for substantial employment shares.', 'TRUE — Growth can move a firm through SME tiers sequentially.'], '3/5', 18, 'full' ),
( '3.4', 'CASE 3.4.19', 'EU micro grant logic', 'Analyze a small IT-support venture consider an EU micro-enterprise grant. Evaluate the following economic assertions:', ARRAY['Forty-five staff and €9.5m turnover together meet EU small enterprise thresholds.', 'Thirty-eight staff fits the small employee ceiling below fifty.', '€1.8m turnover stays within the micro turnover cap of €2m.', 'Six employees fit the micro staff ceiling even when turnover exceeds €2m.', 'Nine employees satisfy the micro staff ceiling of fewer than ten people.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Both staff below fifty and turnover below €10m satisfy small criteria.', 'TRUE — Thirty-eight is within the small staff limit.', 'TRUE — €1.8m meets the micro turnover threshold.', 'TRUE — Six staff meets the micro headcount test though turnover may fail.', 'TRUE — Nine is below the ten-person micro limit.'], '4/5', 19, 'full' ),
( '3.4', 'CASE 3.4.20', 'Micro OR financial logic', 'Analyze how EU micro financial tests combine turnover and balance sheet figures. Evaluate the following economic assertions:', ARRAY['Micro firms are excluded from SME statistics because they are too small to register.', 'Eight staff proves a firm is micro without checking turnover or balance sheet.', 'Two hundred and forty employees fits the medium staff ceiling below two hundred and fifty.', '€48m turnover is within the €50m medium turnover cap.', 'Large classification removes all legal duties to publish any financial information.'], ARRAY[false, false, true, true, false], ARRAY['FALSE — Micro firms are included in SME counts and definitions.', 'FALSE — Financial caps must also be satisfied for micro status.', 'TRUE — 240 is below the 250-person medium limit.', 'TRUE — €48m meets the medium turnover threshold.', 'FALSE — Large firms face reporting duties rather than exemption.'], '4/5', 20, 'full' ),
( '3.4', 'CASE 3.4.21', 'Small €10m cap recall', 'Analyze EU small-enterprise financial limits alongside staff criteria. Evaluate the following economic assertions:', ARRAY['€180k turnover is well below the €2m micro turnover cap.', 'A retailer is micro because turnover is under €10m despite thirty staff.', 'Four staff with €600k turnover can qualify as micro when financial caps are met.', 'Two hundred staff with €49m turnover and a €42m balance sheet can satisfy medium thresholds.', 'One hundred and twenty-five staff with €25m turnover and €30m balance sheet can satisfy medium thresholds.'], ARRAY[true, false, true, true, true], ARRAY['TRUE — €180k meets the micro turnover threshold.', 'FALSE — Staff above ten and turnover above €2m exclude micro; small may apply.', 'TRUE — Low headcount and turnover can satisfy micro criteria.', 'TRUE — All three metrics can meet medium caps together.', 'TRUE — Staff and both financial figures can meet medium caps.'], '2/5', 21, 'full' ),
( '3.4', 'CASE 3.4.22', 'Medium balance sheet breach', 'Analyze a company has one hundred staff, €30m turnover, and a €43.5m balance sheet. Evaluate the following economic assertions:', ARRAY['Thirty staff with €9.9m turnover satisfies EU small enterprise thresholds.', 'A firm is small because turnover is only €25m despite one hundred twenty-five staff.', 'One hundred staff with €30m turnover fits the medium staff and turnover bands.', '€2m is the micro turnover ceiling in the EU SME table.', 'Nine staff fits the micro employee ceiling pending turnover verification.'], ARRAY[true, false, true, true, true], ARRAY['TRUE — Both metrics meet small staff and turnover caps.', 'FALSE — 125 staff exceeds small staff limit despite moderate turnover.', 'TRUE — 100 staff and €30m turnover can meet medium thresholds pending balance sheet.', 'TRUE — €2m turnover cap applies to micro enterprises.', 'TRUE — Nine is below the ten-person micro limit.'], '5/5', 22, 'full' ),
( '3.4', 'CASE 3.4.23', 'SME policy prevalence', 'Analyze policy makers note SMEs make up about ninety-nine percent of EU businesses. Evaluate the following economic assertions:', ARRAY['Micro, small, and medium are identical categories with the same staff ceilings.', '€43m is the medium balance sheet ceiling in the EU SME table.', '€10m is the small turnover ceiling in the EU SME table.', '€2m is the micro balance sheet ceiling in the EU SME table.', '€50m is the medium turnover ceiling in the EU SME table.'], ARRAY[false, true, true, true, true], ARRAY['FALSE — Each tier has distinct staff and financial thresholds.', 'TRUE — €43m balance sheet cap applies to medium enterprises.', 'TRUE — €10m turnover cap applies to small enterprises.', 'TRUE — €2m balance sheet cap applies to micro enterprises.', 'TRUE — €50m turnover cap applies to medium enterprises.'], '2/5', 23, 'full' ),
( '3.4', 'CASE 3.4.24', 'Growth micro to small', 'Consider a small IT-support venture plan to hire staff and expand turnover. Evaluate the following economic assertions:', ARRAY['Village location prevents micro classification regardless of size metrics.', '€40m turnover alone is sufficient proof of medium enterprise status.', 'SME status depends on official headcount and financial thresholds, not on industry sector.', 'Meeting either the medium turnover cap or the medium balance sheet cap can satisfy the financial test.', 'Micro status can be granted when balance sheet totals alone stay within the micro financial ceiling.'], ARRAY[false, false, true, true, true], ARRAY['FALSE — Location does not override EU size thresholds.', 'FALSE — Medium requires sub-250 staff plus financial tests.', 'TRUE — Sector does not override EU size threshold tests.', 'TRUE — Only one financial measure must qualify for medium status.', 'TRUE — Only one financial measure must qualify for micro status.'], '3/5', 24, 'full' ),
( '3.4', 'CASE 3.4.25', 'A components manufacturer accounting contrast', 'Analyze reporting expectations for a components manufacturer and a micro village supplier. Evaluate the following economic assertions:', ARRAY['Expanding headcount and turnover past small-tier limits can push a firm into the medium category.', 'Three thousand staff far exceeds the two hundred and fifty employee medium ceiling.', 'Outgrowing micro employee or financial caps can move a workshop into the small enterprise band.', 'Export activity does not override EU SME threshold tests for classification.', '€200m turnover far exceeds the €50m medium turnover ceiling.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Progression to medium replaces small when medium limits are satisfied.', 'TRUE — 3,000 staff places a firm outside medium limits.', 'TRUE — Progression to small replaces micro when small limits are satisfied.', 'TRUE — Cross-border sales do not replace official size criteria.', 'TRUE — €200m turnover places a firm outside medium limits.'], '3/5', 25, 'full' ),
( '3.4', 'CASE 3.4.26', 'Medium €50m turnover cap', 'Analyze the EU medium enterprise turnover limit alongside other criteria. Evaluate the following economic assertions:', ARRAY['€2.1m turnover exceeds the €2m micro turnover cap.', '€10.4m turnover exceeds the €10m small turnover cap.', '€52m turnover exceeds the €50m medium turnover cap.', 'Firms skip the small tier whenever they hire a tenth employee.', 'A €44m balance sheet exceeds the €43m medium balance sheet cap.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — €2.1m breaks the micro turnover threshold.', 'TRUE — €10.4m breaks the small turnover threshold.', 'TRUE — €52m breaks the medium turnover threshold.', 'FALSE — Ten employees fail micro but small requires further staff and turnover tests.', 'TRUE — €44m breaks the medium balance sheet threshold.'], '2/5', 26, 'full' ),
( '3.4', 'CASE 3.4.27', 'Micro versus small confusion', 'Analyze an examiner checks claims mixing micro and small staff ceilings. Evaluate the following economic assertions:', ARRAY['Eight employees fall short of the micro tier''s fewer-than-ten staff threshold.', 'A seven-person workforce remains within micro staffing limits under EU rules.', 'Exactly ten staff satisfies the micro requirement of fewer than ten employees.', 'Exactly two hundred fifty staff satisfies the medium requirement of fewer than two hundred and fifty.', 'Exactly fifty staff satisfies the small enterprise requirement of fewer than fifty.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Eight is below the ten-person micro limit.', 'TRUE — Seven is below the ten-person micro limit.', 'FALSE — Ten is not fewer than ten; the micro staff test fails.', 'FALSE — 250 is not fewer than 250; the medium staff test fails.', 'FALSE — Fifty is not fewer than fifty; the small staff test fails.'], '4/5', 27, 'full' ),
( '3.4', 'CASE 3.4.28', 'SME finance verification', 'Analyze a medium-sized exporter seeks a bank loan with EU guarantee backing. Evaluate the following economic assertions:', ARRAY['One hundred and eighty employees remain within the medium staffing band below two hundred and fifty.', 'A medium exporter employing one hundred workers stays under the two-hundred-fifty employee ceiling.', '€2.1m turnover still meets the micro turnover cap of €2m.', '€10.4m turnover still meets the small turnover cap of €10m.', 'One hundred and twenty workers on payroll still qualifies as medium under the staff cap.'], ARRAY[true, true, false, false, true], ARRAY['TRUE — 180 is below the 250-person medium limit.', 'TRUE — 100 is below the 250-person medium limit.', 'FALSE — €2.1m exceeds the €2m micro turnover threshold.', 'FALSE — €10.4m exceeds the €10m small turnover threshold.', 'TRUE — 120 is below the 250-person medium limit.'], '3/5', 28, 'full' ),
( '3.4', 'CASE 3.4.29', 'Local repair shop profile', 'Consider a technician who runs a repair shop with one apprentice, two staff total, and €180k turnover. Evaluate the following economic assertions:', ARRAY['€52m turnover still meets the medium turnover cap of €50m.', 'A €44m balance sheet still meets the medium balance sheet cap of €43m.', 'Two workers on payroll automatically places the shop above the micro employee band.', 'Employing six people forces the business out of micro classification on headcount alone.', 'Two hundred staff fits the medium employee ceiling below two hundred and fifty.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — €52m exceeds the €50m medium turnover threshold.', 'FALSE — €44m exceeds the €43m medium balance sheet threshold.', 'FALSE — Two is below ten and fits the micro staff ceiling.', 'FALSE — Six is below ten and fits the micro staff ceiling.', 'TRUE — 200 is below the 250-person medium limit.'], '1/5', 29, 'full' ),
( '3.4', 'CASE 3.4.30', 'Combined criteria requirement', 'Analyze whether meeting one SME criterion alone guarantees overall SME status. Evaluate the following economic assertions:', ARRAY['Forty-five staff fits the small employee ceiling below fifty.', 'Thirty staff exceeds the small employee ceiling of fewer than fifty.', 'One hundred and eighty staff fits the small employee ceiling below fifty.', 'Two hundred staff fits the small employee ceiling below fifty.', 'Three thousand staff fits the medium employee ceiling below two hundred and fifty.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — 45 is below the fifty-employee small limit.', 'FALSE — Thirty is below fifty and fits the small staff ceiling.', 'FALSE — 180 exceeds the fifty-employee small limit.', 'FALSE — 200 exceeds the fifty-employee small limit.', 'FALSE — 3,000 far exceeds the 250-person medium limit.'], '4/5', 30, 'full' ),
( '3.4', 'CASE 3.4.31', 'Three thousand staff group', 'Consider a tech group that employs three thousand staff with €200m turnover. Evaluate the following economic assertions:', ARRAY['Turnover of €1.8m exceeds the micro turnover cap of €2m.', 'Micro firms are included in SME counts and MSME groupings.', 'Ten thousand a components manufacturer staff fits the medium employee ceiling below two hundred and fifty.', 'Turnover of €9.5m exceeds the small turnover cap of €10m.', 'Turnover of €49m exceeds the medium turnover cap of €50m.'], ARRAY[false, true, false, false, false], ARRAY['FALSE — €1.8m is within the €2m micro turnover ceiling.', 'TRUE — Micro enterprises form part of the SME category.', 'FALSE — 10,000 far exceeds the 250-person medium limit.', 'FALSE — €9.5m is within the €10m small turnover ceiling.', 'FALSE — €49m is within the €50m medium turnover ceiling.'], '3/5', 31, 'full' ),
( '3.4', 'CASE 3.4.32', 'Architect turnover edge', 'Analyze an architect practice has nine staff, €2.05m turnover, and a €1.6m balance sheet. Evaluate the following economic assertions:', ARRAY['A firm with forty-five staff is micro because it employs fewer than fifty people.', 'Large firms face reporting duties rather than exemption from financial disclosure.', 'Because SMEs are numerous by count, SME-focused policy reaches most EU businesses.', 'Few large firms can still account for substantial employment despite being rare by count.', 'SME failures can still affect employees, suppliers, and local communities.'], ARRAY[false, true, true, true, true], ARRAY['FALSE — Forty-five staff exceeds the micro ceiling of fewer than ten.', 'TRUE — Large classification brings reporting obligations.', 'TRUE — High SME share by number shapes EU business policy.', 'TRUE — Large employers can be few in number yet significant in jobs.', 'TRUE — SME insolvency has stakeholder effects beyond firm count statistics.'], '5/5', 32, 'full' ),
( '3.4', 'CASE 3.4.33', 'SME count statistic meaning', 'Analyze what the ninety-nine percent SME figure implies about EU business structure. Evaluate the following economic assertions:', ARRAY['A firm with thirty-eight staff is micro because it employs fewer than fifty people.', 'Small status requires fewer than fifty staff plus turnover at or below €10m.', 'Medium status requires fewer than two hundred and fifty staff plus a qualifying financial test.', 'EU support programmes use standard SME thresholds to verify applicant eligibility.', 'A firm with nine staff still needs turnover or balance sheet data to confirm micro status.'], ARRAY[false, true, true, true, true], ARRAY['FALSE — Thirty-eight staff exceeds the micro ceiling of fewer than ten.', 'TRUE — Small combines staff ceiling with the €10m turnover cap.', 'TRUE — Medium combines staff ceiling with turnover or balance sheet caps.', 'TRUE — Finance schemes rely on official size criteria.', 'TRUE — Financial caps must be verified alongside headcount.'], '2/5', 33, 'full' ),
( '3.4', 'CASE 3.4.34', 'Medium turnover breach path', 'Analyze a firm has one hundred twenty staff, €52m turnover, and a €40m balance sheet. Evaluate the following economic assertions:', ARRAY['Medium status follows from international operations regardless of headcount.', 'A components manufacturer is classified as large under EU thresholds because headcount far exceeds medium limits.', 'Micro status requires fewer than ten staff plus turnover at or below €2m or balance sheet at or below €2m.', 'a neighbourhood bakery with six staff meets the micro headcount test.', 'A firm with eight staff still needs turnover or balance sheet data to confirm micro status.'], ARRAY[false, true, true, true, true], ARRAY['FALSE — Medium status depends on EU thresholds, not geographic scope.', 'TRUE — a components manufacturer''s ~10,000 staff exceeds the 250-person medium ceiling.', 'TRUE — Micro combines staff ceiling with one financial cap.', 'TRUE — Six employees is below the ten-person micro limit.', 'TRUE — Financial caps must be verified alongside headcount.'], '5/5', 34, 'full' ),
( '3.4', 'CASE 3.4.35', 'Small to medium transition', 'Analyze a family manufacturer grows to one hundred eighty staff and €45m turnover. Evaluate the following economic assertions:', ARRAY['A village craft business with four staff meets the micro headcount test.', 'Micro status follows from supplying larger manufacturers regardless of headcount.', 'A local repair shop with two staff meets the micro headcount test.', 'A retailer with thirty staff meets the small headcount test.', 'SME classification is optional for firms seeking EU support programmes.'], ARRAY[true, false, true, true, false], ARRAY['TRUE — Four employees is below the ten-person micro limit.', 'FALSE — Supplier relationships do not determine EU size classification.', 'TRUE — Two employees is below the ten-person micro limit.', 'TRUE — Thirty employees is below the fifty-person small limit.', 'FALSE — Official SME criteria gate access to many support schemes.'], '4/5', 35, 'full' ),
( '3.4', 'CASE 3.4.36', 'EU table tier pairing', 'Analyze each enterprise tier with its paired EU threshold logic. Evaluate the following economic assertions:', ARRAY['An architect practice with nine staff meets the micro headcount test.', 'A family firm with exactly ten staff fails the micro headcount test.', 'A textile plant with exactly two hundred fifty staff fails the medium headcount test.', 'A wholesaler with thirty-eight staff meets the small headcount test.', 'A logistics company with exactly fifty staff fails the small headcount test.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Nine employees is below the ten-person micro limit.', 'TRUE — Ten is not fewer than ten, so micro staff test fails.', 'TRUE — 250 is not fewer than 250, so medium staff test fails.', 'TRUE — Thirty-eight employees is below the fifty-person small limit.', 'TRUE — Fifty is not fewer than fifty, so small staff test fails.'], '3/5', 36, 'full' ),
( '3.4', 'CASE 3.4.37', 'Small bakery versus large manufacturer', 'Compare a neighbourhood bakery with a large components manufacturer when discussing business size. Evaluate the following economic assertions:', ARRAY['The medium financial test treats €43m as the upper balance sheet bound.', 'Micro eligibility includes balance sheet totals that do not exceed €2m.', 'Small-enterprise turnover qualification allows figures up to the €10m ceiling.', 'Micro turnover qualification permits annual sales up to €2m under EU tables.', 'Medium turnover qualification permits figures up to €50m when other criteria hold.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — €43m is the medium balance sheet ceiling.', 'TRUE — €2m is the micro balance sheet ceiling.', 'TRUE — €10m is the small turnover ceiling.', 'TRUE — €2m is the micro turnover ceiling.', 'TRUE — €50m is the medium turnover ceiling.'], '2/5', 37, 'full' ),
( '3.4', 'CASE 3.4.38', 'Incomplete application data', 'Analyze an agency reviews an applicant with nine staff but incomplete turnover data. Evaluate the following economic assertions:', ARRAY['Fifty-one employees instantly relegate a firm to large-enterprise status with no intermediate tier.', 'Both turnover and balance sheet must fail for medium status to be denied.', 'The ninety-nine percent SME statistic refers to business numbers, not GDP share.', 'Meeting the turnover threshold for medium size does not let the firm ignore the balance-sheet criterion entirely.', 'Eleven employees immediately push a business into the large-firm category skipping SME tiers.'], ARRAY[false, false, true, false, false], ARRAY['FALSE — Fifty staff fails small but medium tier may still apply.', 'FALSE — Breaching either financial cap can block medium classification.', 'TRUE — The statistic measures business counts rather than GDP share.', 'FALSE — Either financial cap can disqualify medium status when breached.', 'FALSE — Ten staff fails micro but small and medium tiers still exist.'], '4/5', 38, 'full' ),
( '3.4', 'CASE 3.4.39', 'Medium turnover-only breach', 'Analyze a firm has two hundred staff, €55m turnover, and a €42m balance sheet. Evaluate the following economic assertions:', ARRAY['Passing the balance-sheet test alone does not drop the turnover test from the medium-size classification.', 'Grant schemes ignore official micro thresholds when the applicant is a local shop.', 'A firm with nine staff is confirmed micro without turnover documentation.', 'Both turnover and balance sheet must pass for micro status to be granted.', 'Definitions actively shape finance access and regulatory treatment of firms.'], ARRAY[false, false, false, false, true], ARRAY['FALSE — Either financial cap can disqualify medium status when breached.', 'FALSE — Support programmes use standard EU micro criteria.', 'FALSE — Financial thresholds are mandatory for micro confirmation.', 'FALSE — Only one financial measure must qualify for micro status.', 'TRUE — SME labels affect support and reporting, not just description.'], '5/5', 39, 'full' ),
( '3.4', 'CASE 3.4.40', 'SME employment nuance', 'Analyze claims linking SME business counts with employment patterns. Evaluate the following economic assertions:', ARRAY['Meeting one SME criterion alone does not guarantee overall SME status in a tier.', 'Micro enterprises dominate EU business counts as part of the broader SME group.', 'A firm with eight staff is confirmed micro without turnover documentation.', 'Progression through SME tiers follows successive threshold crossings as firms grow.', 'The EU micro cap for turnover is €10m rather than €2m.'], ARRAY[true, true, false, true, false], ARRAY['TRUE — Each tier requires joint staff and financial tests.', 'TRUE — Micro firms contribute to the ~99% SME majority by number.', 'FALSE — Financial thresholds are mandatory for micro confirmation.', 'TRUE — Firms can move from micro to small to medium with growth.', 'FALSE — €10m is the small turnover cap, not the micro cap.'], '3/5', 40, 'full' ),
( '3.4', 'CASE 3.4.41', 'Financial cap literacy', 'Analyze students must recall EU financial caps. Evaluate the following economic assertions:', ARRAY['Small enterprises must satisfy staff limits and the €10m turnover cap.', 'Classification review requires both headcount and financial figures for EU SME tiers.', 'A firm crossing medium limits becomes ineligible for certain EU SME finance programmes.', 'Medium enterprises must satisfy staff limits and at least one financial cap.', 'A tech group with three thousand staff is treated as large under EU size rules.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — Small uses combined staff and turnover criteria.', 'TRUE — Incomplete data prevents reliable SME verification.', 'TRUE — SME-tied support excludes firms above medium thresholds.', 'TRUE — Medium uses combined staff and financial criteria.', 'TRUE — 3,000 employees exceeds all SME staff ceilings.'], '3/5', 41, 'full' ),
( '3.4', 'CASE 3.4.42', 'Micro local economy role', 'Analyze the economic role of micro firms such as local shops and workshops. Evaluate the following economic assertions:', ARRAY['Accounting rule sets can differ between micro firms and large groups such as a components manufacturer.', 'EU SME tables pair each tier with distinct staff and financial ceilings.', 'The EU medium cap for balance sheet is €50m rather than €43m.', 'Labeling €10m as the medium turnover ceiling misstates the EU threshold for that tier.', 'Calling €2m the small turnover cap incorrectly swaps micro and small financial limits.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — Size classification affects applicable accounting rules.', 'TRUE — Micro, small, and medium each have separate threshold rows.', 'FALSE — €43m is the medium balance sheet cap in the EU table.', 'FALSE — €10m is the small turnover cap, not the medium cap.', 'FALSE — €2m is the micro turnover cap, not the small cap.'], '2/5', 42, 'full' ),
( '3.4', 'CASE 3.4.43', 'Staff-only exam trap', 'Analyze a case lists eight staff and asks whether SME status is certain. Evaluate the following economic assertions:', ARRAY['A small IT-support venture count as a large enterprise because their bakery supplies many customers.', 'One hundred and twenty staff with €52m turnover fails the medium turnover test.', 'About ninety-nine percent of EU employees work in SMEs because ninety-nine percent of firms are SMEs.', 'A components manufacturer counts as a medium enterprise because its Austrian headquarters defines EU size.', 'Two hundred staff with €55m turnover fails the medium turnover test.'], ARRAY[false, true, false, false, true], ARRAY['FALSE — a small IT-support venture illustrate micro-scale operations, not large enterprise status.', 'TRUE — €52m exceeds the €50m medium turnover cap.', 'FALSE — The statistic refers to business numbers, not employment share.', 'FALSE — a components manufacturer''s ~10,000 staff exceeds medium limits.', 'TRUE — €55m exceeds the €50m medium turnover cap.'], '5/5', 43, 'full' ),
( '3.4', 'CASE 3.4.44', 'Leaving SME status effects', 'Analyze a firm crosses medium limits and becomes large. Evaluate the following economic assertions:', ARRAY['An engineering firm with two hundred staff can meet the medium staff test.', 'Grant eligibility for micro enterprises requires meeting official micro thresholds.', 'SME verification for bank loans may require proof of headcount and turnover bands.', 'A manufacturer with two hundred forty staff can meet the medium staff test.', 'One hundred and eighty staff with €45m turnover can meet medium staff and turnover tests.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — 200 is below the 250-person medium limit.', 'TRUE — Micro grants use standard EU micro criteria.', 'TRUE — Lenders check official SME thresholds for guarantee schemes.', 'TRUE — 240 is below the 250-person medium limit.', 'TRUE — 180 staff and €45m turnover fit medium ceilings.'], '3/5', 44, 'full' ),
( '3.4', 'CASE 3.4.45', 'Small retailer headroom', 'Consider a retailer that has thirty staff and €9.9m turnover. Evaluate the following economic assertions:', ARRAY['Medium turnover of €49m stays within the €50m medium cap.', 'Micro enterprises are omitted from the ninety-nine percent SME business count.', 'Small turnover of €9.5m stays within the €10m small cap.', 'A firm at eight staff is not confirmed as micro without financial verification.', 'A firm becomes large immediately upon employing a tenth worker.'], ARRAY[true, false, true, true, false], ARRAY['TRUE — €49m meets the medium turnover threshold.', 'FALSE — Micro firms are included in SME counts.', 'TRUE — €9.5m meets the small turnover threshold.', 'TRUE — Headcount alone does not confirm micro status.', 'FALSE — Ten staff fails micro but further tiers depend on additional tests.'], '2/5', 45, 'full' ),
( '3.4', 'CASE 3.4.46', 'Medium mid-range profile', 'Analyze medium classification for a firm with one hundred twenty-five staff, €25m turnover, and €30m balance sheet. Evaluate the following economic assertions:', ARRAY['A firm at nine staff is not confirmed as micro without financial verification.', 'A firm becomes large immediately upon reaching €2.1m turnover.', 'Micro turnover of €1.5m stays within the €2m micro cap.', 'One criterion alone is enough for small status when staff are forty-five.', 'One criterion alone is enough for medium status when turnover is €40m.'], ARRAY[true, false, true, false, false], ARRAY['TRUE — Headcount alone does not confirm micro status.', 'FALSE — Turnover above €2m removes micro status but small or medium may apply.', 'TRUE — €1.5m meets the micro turnover threshold.', 'FALSE — Small requires turnover at or below €10m as well.', 'FALSE — Medium requires sub-250 staff plus financial tests.'], '2/5', 46, 'full' ),
( '3.4', 'CASE 3.4.47', 'SME synthesis review', 'Analyze EU SME classification principles for exam review. Evaluate the following economic assertions:', ARRAY['Headcount alone confirms small status for a fifty-employee logistics company.', 'Incomplete turnover data still proves micro status when staff are nine.', 'Micro turnover of €1.6m balance sheet context still allows €1.6m balance sheet under €2m cap.', 'Supplier status to phone makers determines a components manufacturer size classification.', 'Headcount alone confirms micro status for a ten-employee family firm.'], ARRAY[false, false, true, false, false], ARRAY['FALSE — Fifty staff fails the below-fifty small staff test.', 'FALSE — Financial thresholds are mandatory for micro confirmation.', 'TRUE — €1.6m meets the micro balance sheet threshold.', 'FALSE — Headcount and financial thresholds determine EU size classification.', 'FALSE — Ten staff fails the below-ten micro staff test.'], '1/5', 47, 'full' ),
( '3.4', 'CASE 3.4.48', 'Turnover-only student error', 'Analyze a student argues a firm is medium because turnover is €40m. Evaluate the following economic assertions:', ARRAY['Micro turnover of €1.7m balance sheet total stays within the €2m micro balance sheet cap.', 'A small IT-support venture serve as micro-scale examples alongside a components manufacturer as a large firm.', 'SME classification principles combine staff ceilings with turnover and/or balance sheet caps.', 'About ninety-nine percent of EU businesses are SMEs by number rather than by employment share alone.', 'Medium balance sheet of €42m stays within the €43m medium cap.'], ARRAY[true, true, true, true, true], ARRAY['TRUE — €1.7m meets the micro balance sheet threshold.', 'TRUE — Course examples contrast micro local ventures with a components manufacturer scale.', 'TRUE — Combined criteria define EU SME tiers in the official table.', 'TRUE — The statistic measures business counts.', 'TRUE — €42m meets the medium balance sheet threshold.'], '4/5', 48, 'full' ),
( '3.4', 'CASE 3.4.49', 'Village craft micro profile', 'Analyze a village craft business has four staff and €600k turnover. Evaluate the following economic assertions:', ARRAY['An SME may lose access to certain guarantee schemes after reclassification as large.', 'Micro enterprises remain part of MSME groupings alongside small and medium firms.', 'Crossing the medium employee or financial ceiling moves classification toward large enterprise status.', 'Village craft workshops are exempt from EU micro turnover caps.', 'Official size categories matter for EU-backed finance and support programme access.'], ARRAY[true, true, true, false, true], ARRAY['TRUE — SME-tied finance programmes typically exclude large firms.', 'TRUE — MSME terminology covers micro, small, and medium categories together.', 'TRUE — Exceeding medium thresholds exits SME bands.', 'FALSE — Official staff and financial tests determine micro status.', 'TRUE — Definitions gate eligibility for SME support.'], '1/5', 49, 'full' ),
( '3.4', 'CASE 3.4.50', 'SME ladder progression', 'Analyze a growing firm on the SME ladder as it adds staff and sales. Evaluate the following economic assertions:', ARRAY['EU SME definitions apply equally regardless of whether a firm operates locally or nationally.', 'Balance sheet totals can disqualify medium status even when turnover appears moderate.', 'Staff headcount alone cannot confirm small status without checking the turnover cap.', 'Medium status requires both turnover and balance sheet below their caps simultaneously.', 'Small status ignores turnover when staff remain below fifty.'], ARRAY[true, true, true, false, false], ARRAY['TRUE — Geographic scope does not replace official EU size thresholds.', 'TRUE — The medium balance sheet cap is binding alongside staff limits.', 'TRUE — Small classification requires both staff and turnover tests.', 'FALSE — Only one financial measure must qualify alongside staff for medium status.', 'FALSE — Small classification requires turnover at or below €10m.'], '3/5', 50, 'full' ),
( '3.5', 'CASE 3.5.01', 'Local bakery scope', 'Consider a neighbourhood bakery that serves walk-in customers within one district. Evaluate the following economic assertions:', ARRAY['A firm is local only if it employs fewer than ten people regardless of customer location.', 'National businesses sell in every country on the same continent by definition.', 'Local and regional firms often face challenges raising funds and finding enough customers.', 'Local and regional businesses typically operate in a limited geographic area with customers nearby.', 'Regional businesses operate worldwide but with smaller marketing budgets than multinationals.'], ARRAY[false, false, true, true, false], ARRAY['FALSE — Local scope is defined by operating area and customer proximity, not SME headcount.', 'FALSE — National scope is confined to the home country, not continental reach.', 'TRUE — Funding access and customer reach are cited challenges for geographically focused firms.', 'TRUE — Local/regional scope is defined by a restricted operating area and proximate customers.', 'FALSE — Regional firms remain within a limited territory, not worldwide.'], '2/5', 1, 'full' ),
( '3.5', 'CASE 3.5.02', 'Regional supplier reach', 'Consider a regional dairy that delivers to shops across one province. Evaluate the following economic assertions:', ARRAY['Undercapitalisation is unknown among local firms once they register for VAT.', 'A national business operates within its home country rather than across foreign markets.', 'Undercapitalisation is a risk particularly associated with smaller geographically focused firms.', 'A website visible abroad makes a firm multinational even without cross-border sales.', 'National operations typically involve a longer supply chain than a very local producer.'], ARRAY[false, true, true, false, true], ARRAY['FALSE — Registration does not remove capital constraints noted for local/regional firms.', 'TRUE — National scope confines activity to the home country.', 'TRUE — Limited capital is linked to local and regional business constraints.', 'FALSE — Online presence alone does not equal cross-border production or sales.', 'TRUE — National activity lengthens supply chains compared with very local operations.'], '3/5', 2, 'full' ),
( '3.5', 'CASE 3.5.03', 'National retailer chain', 'Consider a home-country supermarket chain that sources nationally but sells only domestically. Evaluate the following economic assertions:', ARRAY['Globalisation means every small shop becomes a multinational overnight.', 'International or multinational firms make and/or sell in more than one country.', 'International business uses one legal system worldwide so compliance is uniform.', 'National supply chains are shorter than local ones because transport is faster domestically.', 'Local businesses face no difficulty finding customers because proximity guarantees demand.'], ARRAY[false, true, false, false, false], ARRAY['FALSE — Globalisation refers to rising multinational enterprise activity, not all shops.', 'TRUE — Cross-border production or sales define international/multinational scope.', 'FALSE — Multiple legal systems apply across countries.', 'FALSE — states national chains are longer than local ones.', 'FALSE — Local/regional firms can struggle to find enough customers despite nearby catchments.'], '3/5', 3, 'full' ),
( '3.5', 'CASE 3.5.04', 'Multinational manufacturer scope', 'Consider A components manufacturer that manufactures and sells across several countries. Evaluate the following economic assertions:', ARRAY['Regional scope allows unlimited customers anywhere on the globe.', 'Globalisation is described as the rise of multinational enterprises operating across borders.', 'Selling nationwide while owners stay in one town makes the business local by residence.', 'International business must cope with different cultures, languages, and currencies.', 'Operating internationally lengthens the supply chain and crosses legal and economic systems.'], ARRAY[false, true, false, true, true], ARRAY['FALSE — Regional businesses serve a limited area, not global markets.', 'TRUE — Globalisation is tied to spreading multinational enterprise activity.', 'FALSE — Nationwide sales indicate national scope despite owner location.', 'TRUE — Cultures, languages, and currencies are named complications of international business.', 'TRUE — International scope brings longer chains plus differing legal and economic frameworks.'], '2/5', 4, 'full' ),
( '3.5', 'CASE 3.5.05', 'Local customer proximity', 'Analyze what defines a local or regional business by customer and operating area. Evaluate the following economic assertions:', ARRAY['Manufacturing in one country and selling in another indicates international/multinational scope.', 'Customer proximity and a limited service area characterise local business scope.', 'Regional businesses still operate within a defined territory rather than worldwide.', 'Selling only within the home country fits national rather than international scope.', 'A multinational must produce in every country where it sells by definition.'], ARRAY[true, true, true, true, false], ARRAY['TRUE — Cross-border production combined with foreign sales exceeds national boundaries.', 'TRUE — Local firms chiefly serve nearby customers within a restricted area.', 'TRUE — Regional scope remains geographically bounded though broader than a single neighbourhood.', 'TRUE — Home-country-only sales align with national classification.', 'FALSE — Making and/or selling in more than one country suffices; both everywhere is not required.'], '2/5', 5, 'full' ),
( '3.5', 'CASE 3.5.06', 'Regional funding challenge', 'Consider a regional craft firm that struggles to raise funds and find customers. Evaluate the following economic assertions:', ARRAY['A components manufacturer operating across countries illustrates a multinational enterprise reinventing its model.', 'Limited capital can constrain a local firm''s ability to expand beyond its immediate market.', 'Currency differences disappear once a firm opens a foreign bank account.', 'Undercapitalisation affects only multinational firms building foreign factories.', 'Culture and language differences matter only to tourist shops, not to manufacturers.'], ARRAY[true, true, false, false, false], ARRAY['TRUE — a components manufacturer exemplifies large-scale multinational scope.', 'TRUE — Undercapitalisation limits growth for geographically focused firms.', 'FALSE — Operating across borders still involves multiple currencies.', 'FALSE — links undercapitalisation chiefly to local/regional business challenges.', 'FALSE — Cultures and languages apply to international business generally.'], '4/5', 6, 'full' ),
( '3.5', 'CASE 3.5.07', 'Undercapitalisation risk', 'Consider undercapitalisation as a challenge linked to smaller geographic scope. Evaluate the following economic assertions:', ARRAY['Importing finished goods for domestic resale makes a firm a manufacturer in two countries.', 'Multiple legal systems apply when a firm conducts business in several countries.', 'Language differences matter for customer contact in international markets.', 'Globalisation excludes service firms and applies only to factories.', 'A longer supply chain is typical when sourcing and selling nationally rather than locally.'], ARRAY[false, true, true, false, true], ARRAY['FALSE — Domestic resale of imports is not the same as producing abroad.', 'TRUE — International operations cross differing legal frameworks.', 'TRUE — Languages are among international business complications.', 'FALSE — Globalisation concerns multinational enterprise broadly, not factories alone.', 'TRUE — National scope implies greater supply chain length than local operations.'], '4/5', 7, 'full' ),
( '3.5', 'CASE 3.5.08', 'National supply chain length', 'Analyze supply chain length for a national manufacturer versus a local workshop. Evaluate the following economic assertions:', ARRAY['Proximity to customers removes any need to seek sales for local firms.', 'National businesses operate in more than one country as long as they use domestic currency.', 'Currency differences arise when trading across international borders.', 'A components manufacturer is a local enterprise because its first plant was in one town.', 'Globalisation reflects more firms producing and selling beyond a single country.'], ARRAY[false, false, true, false, true], ARRAY['FALSE — Finding customers remains a cited challenge for local/regional firms.', 'FALSE — National firms stay within the home country.', 'TRUE — Multiple currencies are part of international business conditions.', 'FALSE — a components manufacturer exemplifies large multinational scope with cross-border activity.', 'TRUE — Rising multinationals underpin the view of globalisation.'], '3/5', 8, 'full' ),
( '3.5', 'CASE 3.5.09', 'International legal complexity', 'Analyze a firm sells in three countries with differing contract laws. Evaluate the following economic assertions:', ARRAY['Regional hauliers moving goods within a territory still face geographic limits compared with national networks.', 'Regional firms can ignore capital needs because banks lend equally in every village.', 'Domestic-only sales and production within one country describe national scope.', 'Cross-border manufacturing is still national if headquarters stays at home.', 'A plumber serving one town operates locally with nearby customers.'], ARRAY[true, false, true, false, true], ARRAY['TRUE — Regional scope is broader than local but remains below national/international reach.', 'FALSE — Raising funds is a stated challenge for local/regional businesses.', 'TRUE — Confining activity to the home country is national classification.', 'FALSE — Production abroad contributes to international/multinational scope.', 'TRUE — Single-town service fits local scope with proximate customers.'], '4/5', 9, 'full' ),
( '3.5', 'CASE 3.5.10', 'Globalisation definition', 'Analyze globalisation as described through the rise of multinational enterprises. Evaluate the following economic assertions:', ARRAY['Cross-border production partnerships indicate international rather than purely national scope.', 'International firms use identical economic systems in every market they enter.', 'A domestic-only rail network is multinational because cargo may originate from imports.', 'Local scope is determined solely by whether the firm is an SME under EU rules.', 'Exporting forty percent of output while producing at home cannot coexist with any national label.'], ARRAY[true, false, false, false, false], ARRAY['TRUE — Foreign production links exceed national boundaries.', 'FALSE — Economic systems differ internationally.', 'FALSE — Domestic routing fits national scope unless operating across countries.', 'FALSE — Geographic scope and SME size classification are separate concepts.', 'FALSE — Export sales cross national boundaries and affect scope labels.'], '2/5', 10, 'full' ),
